window.EXECUTION_MATERIAL=(window.EXECUTION_MATERIAL||[]).concat([{"kind":"text","text":"لم تتعرض النصوص المنظمة لاستئناف أمر الأداء للطعن في الحكم الصادر في الاستئناف. ويجب تفسير هذا السكوت بوجود إرادة تشريعية بأن الطعن في هذا الحكم يخضع للقواعد العامة. وبناء عليه، يكون هذا الحكم قابلا للطعن بالنقض بشرط أن يكون صادرا في نصاب النقض، أي أن تكون قيمة المطالبة الصادر فيها تزيد على خمسمائة ألف درهم. كما أن هذا الحكم- وهو حكم نهائي بالتأكيد- وبصرف النظر عن قيمة المطالبة الصادر فيها، يكون قابلا لالتماس إعادة النظر إذا توافرت إحدى حالاته."},{"kind":"heading","text":"98- (ه) طرق مراجعة أمر الحجز التحفظي الصادر مع أمر الأداء"},{"kind":"text","text":"لا شك أن أمر الحجز التحفظي هو من أبرز الإجراءات التحفظية. وسبق أن رأينا جواز صدوره من قاضي الأداء. فإذا صدر أمر الحجز مع أمر الأداء، فإنه سيخضع في هذه الحالة لحكم البند (5) من المادة 147 والذي ينص على أنه \" تسري القواعد والإجراءات الخاصة بالتظلم من أمر الأداء أو استئنافه على الإجراءات التحفظية الصادرة مع الأمر\". ويجب أن تفهم عبارة الإجراء التحفظي الصادر مع أمر الأداء بمعنى واسع، بحيث يشمل ليس فقط أمر الحجز الذي يستجيب لطلب الإجراء التحفظي وإنما أيضا الصادر بالرفض."},{"kind":"text","text":"وبناء عليه، فإنه إذا كان أمر الأداء قابلا للتظلم، فإن أمر الحجز التحفظي الصادر معه- وبالمعنى الواسع لكلمة الأمر- يكون هو الآخر قابلا للتظلم وفقا للمواعيد والإجراءات الخاصة بالتظلم من أمر الأداء ذاته والمنصوص عليها في المادة 1- 147. ويتفرع عن هذه النتيجة أن أمر الحجز التحفظي هنا لن يكون خاضعا للقواعد العامة للتظلم من الأوامر على العرائض والتي يخضع لها أمر الحجز التحفظي بصفة عامة."},{"kind":"text","text":"أما إذا كان أمر الأداء قابلا للاستئناف، فإن أمر الحجز التحفظي الصادر معه يكون هو الآخر قابلا للاستئناف، وطبقا لقواعد الاستئناف السابق معرفتها والخاصة باستئناف أمر الأداء."},{"kind":"text","text":"وليس معنى ما سبق أن التظلم من أمر الأداء أو استئنافه يجعل التظلم من أمر الحجز أو استئنافه حاصلا بقوة القانون. فالحقيقة أنه يمكن التظلم من أمر الأداء أو استئنافه دون أن يشتمل هذا أو ذاك على طلب مراجعة لأمر الحجز. لكن لا يجوز التظلم من أمر الحجز أو استئنافه استقلالا عن أمر الأداء، وإنما يجب التظلم من هذا الأخير أو استئنافه حتى يمكن مراجعة أمر الحجز بذات الطريق."},{"kind":"text","text":"99- وعلى فرض أن طريق المراجعة كان هو التظلم، فإن شق الحكم الصادر في التظلم من أمر الحجز سيكون نهائيا غير قابل للطعن عليه، نظرا لأن الحكم الصادر في التظلم- وهي عبارة تحتوي على ما يصدر في التظلم من أمر الأداء وكذلك التظلم من أمر الحجز إن وجد- يكون نهائيا ولا يقبل الطعن عليه."},{"kind":"text","text":"ويختلف الحال عندما يكون طريق المراجعة هو الاستئناف. فشق الحكم الصادر من محكمة الاستئناف في أمر الحجز سيكون قابلا للطعن بالنقض طبقا للقواعد العامة، نظرا لقابلية الحكم الصادر في استئناف أمر الأداء- وهي عبارة تحتوي على ما يصدر في استئناف أمر الأداء وكذلك استئناف أمر الحجز إن وجد- للطعن بالنقض من حيث المبدأ. ولا ينطبق هنا حكم المادة 3- 175 والتي تجعل الأحكام الصادرة عن محاكم الاستئناف في \"إجراءات التنفيذ\" غير قابلة للطعن بالنقض. فالواقع أن أمر الحجز التحفظي هو سند للتنفيذ وسابق عليه، وليس إجراء من إجراءاته."},{"kind":"text","text":"الفرع السابع: تنفيذ أمر الأداء"},{"kind":"text","text":"100- لا يقبل التنفيذ من أوامر الأداء سوى الأمر الصادر بالأداء بالمعنى الضيق، أي الصادر بإلزام المدين بالأداء، والمعبر عنه- تجاوزا- بالأمر الصادر بالقبول."},{"kind":"text","text":"وحتى تكتمل لهذا الأمر مقومات السند التنفيذي، يجب أن يكون صادرا مشمولا بالنفاذ المعجل، أو أن يصير نهائيا."},{"kind":"text","text":"وهناك بالفعل إمكانية لصدور أمر الأداء مشمولا بالنفاذ المعجل. السند في ذلك هو المادة 148 والتي قررت صراحة سريان قواعد النفاذ المعجل المقررة بشأن الأحكام على أوامر الأداء. مفاد ذلك إذا أن أمر الأداء قد يعتبر مشمولا بالنفاذ المعجل بقوة القانون، وقد يصدر مشمولا بالنفاذ المعجل القضائي."},{"kind":"text","text":"أما بالنسبة لصيرورة أمر الأداء نهائيا، فإن قابليته دائما للمراجعة من خلال التظلم أو الاستئناف، تجعله يصدر دائما بصفة ابتدائية. ولن يكتسب صفة النهائية إلا إذا صار غير قابل للمراجعة، بأن ينقضي ميعاد التظلم أو الاستئناف دون رفعه. أما إذا تم رفعه، فإنه يجب انتظار الحكم الصادر فيه بتأييد الأمر الذي كان صادرا بالأداء."},{"kind":"text","text":"وتسري على أمر الأداء بعد ذلك القواعد العامة المتعلقة بضرورة الصورة التنفيذية، وبالتالي ضرورة وضع الصيغة التنفيذية. تسري أيضا قاعدة ضرورة اتخاذ مقدمات التنفيذ، ثم يتم اتخاذ إجراءات التنفيذ -المباشر أو بطريق الحجز- المقررة بخصوص كافة السندات التنفيذية."},{"kind":"heading","text":"المطلب الثاني: الأوامر على عرائض"},{"kind":"text","text":"ماهية الأمر على عريضة"},{"kind":"text","text":"101- الأمر على عريضة هو قرار قضائي يصدر بدون تسبيب (مادة 140 - 2)، بناء على عريضة تتضمن طلبا مقدما من أحد الخصوم، دون مواجهة، أي دون إعلان الخصم الآخر ودون مرافعة من أيهما."},{"kind":"text","text":"ويمكن الجزم بأن القرار القضائي هو أمر على عريضة عندما يطلق عليه المشرع هذه التسمية صراحة، أو عندما يكون مطلوبا صدوره بناء على عريضة أو بناء على طلب دون أن تحدث مواجهة."},{"kind":"text","text":"تقسيم"},{"kind":"text","text":"102- سوف نتناول القاضي المختص بإصدار الأمر على عريضة (الفرع الأول)، ثم إجراءات استصداره (الفرع الثاني)، ثم التظلم منه (الفرع الثالث)، وأخيرا الحكم في التظلم والطعن عليه (الفرع الرابع)."},{"kind":"text","text":"الفرع الأول: القاضي المختص بإصدار الأمر"},{"kind":"heading","text":"103- تتعرض المادة 140 للاختصاص العام بإصدار الأوامر على العرائض، وتجعله للمحكمة التي تنظر الدعوى."},{"kind":"text","text":"وقد توحي هذه الصياغة بأن الأوامر على عرائض لا تصدر إلا بمناسبة دعوى مرفوعة بالفعل أمام القضاء، وأن الاختصاص بها للمحكمة المرفوع أمامها هذه الدعوى. إلا أن حقيقة الأمر أنه يجوز استصدار هذه الأوامر على استقلال، أي ولو قبل رفع الدعوى. ليس فقط في الأحوال التي يوجد نص عليها، وإنما في جميع الأحوال التي يوجد فيها وجه لاستصدارها."},{"kind":"text","text":"104- ولكن من هو القاضي المختص بإصدار الأمر على استقلال؟ رغم عدم النص، يمكن القول بأنه قاضي الأمور المستعجلة. سندنا في ذلك الاستصحاب لأكثر من نص صريح عهد به المشرع لهذا القاضي بالاختصاص بإصدار الأمر على عريضة، ثم إنه يصدر بإجراء وقتي، تماما كما هو الحكم المستعجل،. ولكن ليس من السهل في نفس الوقت تخطئة التصور الذي يعهد بهذا الاختصاص لقاضي الدائرة الابتدائية التي كانت ستختص بالدعوى التي يتعلق بها الأمر."},{"kind":"text","text":"الفرع الثاني: إجراءات استصدار الأمر على عريضة"},{"kind":"text","text":"أولا: شكل العريضة"},{"kind":"text","text":"105- هي صحيفة، الكترونية أو ورقية، وفق المعمول به في المحكمة، تودع لدى مكتب إدارة الدعوى، وتقيد بعد استيفاء الرسم في السجل الخاص بذلك، الكترونيا أو ورقيا."},{"kind":"text","text":"يجب أن تشتمل الصحيفة على طلب إلى القاضي المختص، وبعض البيانات الأخرى، ويرفق بها المستندات المؤيدة لها (مادة 1- 140)."},{"kind":"text","text":"ولا يتم إعلان العريضة إلى الطرف الآخر."},{"kind":"text","text":"ثانيا: شكل الأمر"},{"kind":"text","text":"106- يصدر القاضي أمره كتابة على إحدى نسختي العريضة أو الكترونيا، وذلك في اليوم التالي لتقديمها على الأكثر. وهو ميعاد تنظيمي لا يترتب أي بطلان على مخالفته."},{"kind":"text","text":"ولا يلزم من حيث المبدأ ذكر الأسباب التي بني عليها الأمر (مادة 2– 140). ويسجل الأمر في محضر خاص أو في محضر الجلسة، وتحفظ العريضة في الملف."},{"kind":"text","text":"ثالثا: تنفيذ الأمر"},{"kind":"text","text":"107- (أ) يعتبر الأمر على العريضة مشمولا دائما بالنفاذ المعجل بقوة القانون (مادة 1-215-د) وبغير كفالة ما لم ينص في الأمر عليها (مادة 2-215). ويتم تنفيذه بتوجيه كتاب من القاضي الآمر إلى الجهة المعنية بتنفيذه. هذه الجهة قد تكون قاضي التنفيذ، وقد تكون جهة أخرى.. ويتم التنفيذ دون الحاجة إلى صورة تنفيذية، أي دون وضع الصيغة التنفيذية، وكذلك دون إعلان (مادة 3- 140)."},{"kind":"text","text":"108- (ب) يسقط الأمر إذا لم يقدم للتنفيذ خلال خمسة عشر يوما من تاريخ صدوره. وهو سقوط يحدث بقوة القانون دون الحاجة إلى صدور حكم به. ولكنه ليس متعلقا بالنظام العام، وبالتالي ليس لمصدر الأمر والحال كذلك، أن يمتنع من تلقاء نفسه عن إصدار كتابه إلى الجهة المعنية بتنفيذه."},{"kind":"text","text":"ومن ناحية أخرى فإن هذا السقوط لا يمنع من استصدار أمر جديد (مادة 140 -5)."},{"kind":"text","text":"109- (ج) التظلم من الأمر- وهو طريق للمراجعة سوف نتعرف عليه حالا- لا يوقف تنفيذه (مادة 1- 142)، إلا أنه يجوز للمحكمة المرفوع إليها التظلم أن تحكم بوقف تنفيذه بناء على طلب، وبشرط أن تتوافر الخشية من وقوع ضرر جسيم من التنفيذ (المادتان 142 و1-221)."},{"kind":"text","text":"الفرع الثالث: التظلم من الأمر"},{"kind":"text","text":"110- من الطبيعي أن ينظم المشرع طريقا لمراجعة الأمر الصادر على عريضة. فهذه المراجعة هي أولا من أسس التقاضي، وهي ثانيا من ضرورات التقاضي بنظام العريضة، نظرا لصدور الأمر بغير خصومة ومن ثم دون مواجهة، فكان لابد من وسيلة مراجعة تستعيد بها المواجهة فاعليتها."},{"kind":"text","text":"وبالفعل تقر المادة 1- 141 بالحق في التظلم من الأوامر على العرائض. وأول من له هذا الحق هو من صدر عليه الأمر، خاصة وأنه قد صدر في غيبته فلم تسمع أقواله بعد. على أن هذا الحق مقرر أيضا للطالب إذا صدر الأمر برفض طلبه، وكذلك لغيرهما من ذوي الشأن."},{"kind":"text","text":"أولا: الاختصاص بالتظلم"},{"kind":"text","text":"111- الاختصاص بالتظلم وفقا للمادة المذكورة يكون لنفس الجهة التي أصدرت الأمر. هذا التظلم هو بديل عن الطعن بالاستئناف المخصص للأحكام القضائية. فالذي يفرق بينهما أساسا هو أن هذا الطعن- وعلى خلاف التظلم- إنما يكون أمام محكمة أخرى- وأعلى- غير التي صدر عنها الحكم."},{"kind":"text","text":"ثانيا: ميعاد التظلم"},{"kind":"text","text":"112- لا يوجد من حيث المبدأ ميعاد قانوني للتظلم. وليس في ذلك إخلال بالحقوق الإجرائية المشروعة. فالصادر لصالحه الأمر لا يحتاج إلى وجود ميعاد محدد في التشريع ينقضي بانقضائه الحق في التظلم فيكتسب الأمر صفة النهائية. فهو يستطيع تنفيذه فورا لشموله بالنفاذ المعجل."},{"kind":"text","text":"ثالثا: كيفية التظلم"},{"kind":"text","text":"113- يعتبر التظلم من الأمر على عريضة دعوى قضائية وقتية بالنظر إلى أن محلها قرار وقتي. وهي ترفع بصحيفة دعوى، وما يعقب ذلك من إعلان وغير ذلك من إجراءات. أي أنه تنشأ عن التظلم خصومة يصدر فيها حكم قضائي بمعنى الكلمة وإن كان وقتيا. ويكفي للتدليل على ذلك أن الدعوى هي الطريق العادي للتقاضي طالما لم يوجد نص على خلاف ذلك."},{"kind":"text","text":"وإذا كان ما سبق ينطبق بكل سهولة عندما يقدم التظلم استقلالا بالنظر إلى أن الأمر كان صادرا دون أن تكون هناك دعوى منظورة، فإن الوضع يختلف بعض الشيء إذا قدم التظلم تبعا للدعوى الأصلية التي لا تزال تنظرها المحكمة، والتي هي أيضا من أصدرت الأمر. فالتظلم في هذه الحالة لن ينشئ خصومة مستقلة، وإنما سيقدم في ذات الخصومة القائمة. ولذلك تقرر أن يقدم التظلم في هذه الحالة بالإجراءات التي ترفع بها الطلبات العارضة (مادة 3- 141)."},{"kind":"text","text":"رابعا: وقف تنفيذ الأمر بمناسبة التظلم"},{"kind":"text","text":"114- إذا كان الأمر على عريضة قد صدر ملبيا للطلب، فإن للصادر ضده الأمر أن يطلب من المحكمة التي تنظر التظلم، وقف تنفيذ الأمر لحين الفصل في التظلم (مادة 1-221)"},{"kind":"text","text":"خامسا: خضوع بعض الأوامر القضائية للمراجعة وفقا لنظام خاص"},{"kind":"heading","text":"115- نقصد بذلك أولا الأوامر على عرائض بمعنى الكلمة والتي يختص بإصدارها قاضي التنفيذ أو قاضي تنفيذ الأحوال الشخصية."},{"kind":"text","text":"ونقصد بذلك ثانيا طائفة من الأوامر، ورغم حقيقة أنها أوامر على عرائض، إلا أن المشرع قد أدخلها تحت مسمى \"قرارات قاضي التنفيذ\"، وأخضعها بالتالي لنظام المراجعة الخاص بهذه القرارات، والمحكوم أساسا بالمادة 209."},{"kind":"text","text":"هذه الأوامر أو تلك قد تكون قابلة للتظلم (مع وجود تنظيم خاص بالتظلم)، أو قابلة للاستئناف (مع وجود تنظيم خاص للاستئناف)، أو لا تقبل أي طريق للمراجعة."},{"kind":"text","text":"الفرع الرابع: الحكم في التظلم والطعن عليه"},{"kind":"text","text":"116- يصدر في التظلم حكم بتأييد الأمر أو بتعديله أو بإلغائه (مادة 4- 141). هذا الحكم يعتبر حكما وقتيا نظرا لأن التظلم يعد- كما سبق وقلنا- دعوى وقتية. ولذلك فإنه- أي الحكم- يكون قابلا للطعن عليه بالاستئناف في جميع الأحوال. وقد أكدت المادة المذكورة على هذا المعنى."},{"kind":"text","text":"117- ولكن ماذا عن الحكم الذي سيصدر بعد ذلك في الطعن بالاستئناف؟ هذا الحكم لن يكون قابلا للطعن عليه بأي طريق من طرق الطعن غير العادي كالنقض مثلا. يستفاد هذا المعنى من نص المادة السابق ذكرها حين قررت أن الحكم الصادر في التظلم يطعن عليه بطريق \"الاستئناف فقط\"."},{"kind":"text","text":"على أنه يرد على كل ما سبق استثناء يتعلق بالحكم في التظلم الصادر من محكمة الاستئناف ابتداء. فهذا الحكم يختلف عما سبقه من جهة أنه لن يقبل الطعن بالاستئناف بطبيعة الحال، وذلك بالتطبيق للقاعدة الأصولية التي تقرر أن الأحكام الصادرة من محكمة الاستئناف لا تقبل الطعن عليها بالاستئناف. ويختلف من جهة ثانية في أنه سيكون قابلا للطعن عليه بطرق الطعن غير العادية. يستفاد ذلك بسهولة من نص المادة 4- 141 والتي استثنت الحكم في التظلم الصادر من محكمة الاستئناف من قاعدة قابلية الحكم الصادر في التظلم للطعن عليه بالاستئناف فقط. فمفاد هذا الاستثناء أن الطعن في هذا الحكم محل البحث يخضع للقواعد العامة الحاكمة لطرق الطعن ويقبل بالتالي الطعن بالنقض."},{"kind":"heading","text":"المبحث الثالث: محاضر الصلح المصدق عليها"},{"kind":"text","text":"118- انتهينا فيما سبق من نوعي القرارات التي تصدر عادة من المحاكم، وهما الأحكام القضائية والأوامر القضائية. لكن لم ننته بعد من قرارات أخرى تصدر أيضا من المحاكم وتضفي على بعض الأوراق صفة السند التنفيذي. فهناك أولا عقد الصلح الذي يتم بين الخصوم أثناء الخصومة وتصدق عليه المحكمة، أو بمعنى أدق تصدق على محضر الجلسة الذي يتضمنه، ويعتبر سندا تنفيذيا تحت مسمى محاضر الصلح التي تصدق عليها المحاكم. وهناك ثانيا محاضر الصلح أمام جهات التسوية الودية. وهناك ثالثا اتفاق التسوية الذي يتم أمام مركز الوساطة، والذي تصدق عليه المحكمة."},{"kind":"heading","text":"المطلب الأول: محاضر الصلح التي تصدق عليها المحاكم"},{"kind":"heading","text":"119- تذكر المادة 2-212 -ج صراحة محاضر الصلح التي تصدق عليها المحاكم ضمن السندات التنفيذية."},{"kind":"text","text":"فالفرض أن هناك دعوى قضائية مرفوعة أمام المحكمة، وأثناء سير الخصومة اتفق الخصوم على الصلح، سواء من تلقاء أنفسهم، أم بناء على عرض مقدم إليهم من المحكمة. ويقصد بالمحكمة في هذا الشأن، هيئة الحكم التي تنظر الدعوى في مرحلة المحاكمة، أو القاضي المشرف."},{"kind":"text","text":"120- (أ) فإذا حدث الصلح في مرحلة المحاكمة، يتم إثباته- هو ومضمونه- في محضر الجلسة، ثم يوقع على هذا المحضر الخصوم أو وكلائهم المفوض لهم بذلك. وبناء عليه يصدر قرار بانتهاء الخصومة صلحا، ويكون لمحضر الجلسة- أو هو والاتفاق الملحق به - في قوة السند التنفيذي وتعطى للخصوم صورته - العادية وكذلك التنفيذية- وفقا للقواعد المقررة لتسليم صور الأحكام (مادة 81)."},{"kind":"text","text":"121- (ب) ولا يختلف الوضع عندما يحدث الصلح في مرحلة التحضير وتحديدا أمام القاضي المشرف. فهو يصدر قرارا يثبت فيه الصلح ومضمون اتفاق الأطراف، ويكون له قوة السند التنفيذي (مادة 4- 45)."},{"kind":"text","text":"وأيا كانت المرحلة أو القاضي، فكما أن القرار بانتهاء الخصومة صلحا لا يعد حكما قضائيا، فإن قرار إثبات الصلح في محضر الجلسة لا يعد هو الآخر كذلك. فهو في حقيقته عمل من أعمال التوثيق التي يعهد بها المشرع للكاتب العدل كأصل عام، إلا أنه عهد بها إلى القاضي في الحالة محل البحث. ولذلك كان منطقيا أن يدخله المشرع في عداد السندات التنفيذية."},{"kind":"heading","text":"المطلب الثاني: محاضر الصلح أمام جهات التسوية الودية والتي يصدق عليها القاضي المختص"},{"kind":"text","text":"121- لا شك في أن الصلح خير. ولذلك لم يكتف المشرع بما سبق ورأيناه من فتح الباب أمام الخصوم للصلح بعد رفع الدعوى ونشأة الخصومة بالفعل، ومن اعتبار محضر الصلح الذي تصدق عليه المحكمة في هذه الحالة سندا تنفيذيا، وإنما حرص أيضا على تصالح الخصوم في وقت مبكر. فقد جعل الدعوى غير مقبولة إذا رفعت مباشرة إلى المحكمة قبل المرور بمرحلة تتاح فيها فرصة للتسوية الودية. ولذلك اعتبر الصلح الذي يتم في مرحلة التسوية الودية هذه سندا تنفيذيا هو الآخر. ولا شك في انعكاس هذه النتيجة على حسن سير العدالة، من خلال تخفف العبء عن القضاء، إذ لم تعد لصاحب الحق مصلحة في رفع الدعوى للحصول على حكم قضائي بحقه."},{"kind":"text","text":"والمقرر أن هناك جهات ثلاث تسعى لكي يتوصل المتنازعون إلى التسوية الودية، وما ينبني على ذلك من عدم رفع الدعوى إلى القضاء. هذه الجهات تختلف بحسب طبيعة النزاع. فدعاوى الأحوال الشخصية لا يجوز رفعها من حيث المبدأ إلا إذا فشلت التسوية الودية أمام لجنة التوجيه الأسري. بينما الدعاوى العمالية لا تقدم إلى المحكمة مباشرة وإنما من خلال دوائر العمل، والتي تتولى هي تحريك الدعوى إذا فشلت التسوية الودية أمامها. وأخيرا بالنسبة للدعاوى الأخرى يجب أن تستنفد بصددها أولا مرحلة التسوية الودية أمام مراكز التوفيق والمصالحة."},{"kind":"text","text":"وتشجيعا للأفراد على الصلح أمام هذه الجهات، نصت قوانين معظمها على أن تكون محاضر الصلح التي تحررها ذات قوة تنفيذية. وليس في ذلك خروج على المادة 2-212 التي عددت السندات التنفيذية. صحيح أنها ذكرت من محاضر الصلح فقط تلك التي تصدق عليها المحاكم والسابق لنا التعرف عليها، إلا أنها قد اعتبرت سندا تنفيذيا أيضا الأوراق الأخرى التي يعطيها القانون- أي قانون- صفة السند التنفيذي، وهو ما قررته بالفعل القوانين المنظمة لعمل هذه الجهات."},{"kind":"text","text":"122- فعندما تكون المنازعة مما يجب مرورها أولا على مركز التوفيق والمصالحة مثلا، ثم يتم الصلح بين الأفراد أمام المصلح، فإنه يتم إثبات ذلك في محضر يوقع عليه الأطراف والمصلح، ويعتمد هذا المحضر من القاضي المختص بالإشراف على المركز، ويكون لهذا المحضر قوة السند التنفيذي (مادة 15 من القانون الاتحادي بشأن مركز التوفيق والمصالحة)."},{"kind":"heading","text":"المبحث الرابع: أحكام المحكمين"},{"kind":"text","text":"تمهيد"},{"kind":"text","text":"124- لم تنص المادة 2-212 والتي عددت السندات التنفيذية، على أحكام المحكمين كسندات تنفيذية على نحو صريح. ومع ذلك فلا خلاف على تمتع هذه الأحكام بالقوة التنفيذية. الأساس في ذلك يبدأ من المادة المذكورة ذاتها حين قررت أن السندات التنفيذية ليس فقط المذكورة فيها صراحة، وإنما أيضا غيرها من السندات التي يعطيها القانون- أي قانون- هذه الصفة. فإذا رجعنا إلى قانون التحكيم- وهو القانون رقم 6 لسنة 2018 – فإننا نجده يعطي حكم المحكم هذه الصفة بالفعل، على أن يستكمل هذا الحكم إجراء معينا هو صدور أمر قضائي بالمصادقة عليه. يستفاد كل ذلك من المادة 52 من القانون المذكور، والتي قررت أن\".. حكم التحكيم.. يكون له ذات القوة التنفيذية كما لو كان حكما قضائيا، إلا أنه يشترط لتنفيذه الحصول على قرار المصادقة عليه من المحكمة\"."},{"kind":"text","text":"125- ولن تنشغل هذه الدراسة بالنظام القانوني لحكم المحكم، وإنما فقط بالنظام القانوني لقرار المصادقة، فهو مكون أساسي لكي يكتسب هذا الحكم صفة السند التنفيذي."},{"kind":"heading","text":"المطلب الأول: إجراءات الحصول على المصادقة"},{"kind":"text","text":"أولا: الاختصاص بالمصادقة"},{"kind":"text","text":"126- وفقا للمادة 55 من قانون التحكيم، ينعقد الاختصاص بالمصادقة- وهي كما سيتضح لنا فيما بعد عبارة عن أمر قضائي على عريضة بتنفيذ حكم المحكم- لرئيس المحكمة أو من يندبه من قضاتها. والمحكمة المقصودة هنا هي محكمة الاستئناف الاتحادية أو المحلية التي اتفق عليها الأطراف، فإن لم يوجد اتفاق فهي التي جرى ضمن دائرتها التحكيم (مادة 1 من قانون التحكيم)."},{"kind":"text","text":"ثانيا: إجراءات المصادقة"},{"kind":"text","text":"127- رسم المشرع طريق الحصول على قرار المصادقة، وهو مجرد تقديم \"طلب المصادقة على حكم المحكم والأمر بتنفيذه\"، مرفقا بهذا الطلب بعض الأوراق، من بينها صورة من محضر إيداع الحكم (مادة 1- 55). معنى ذلك أنه ليس مطلوبا تقديم صحيفة دعوى. وحتى إذا اعتبرنا هذا الطلب يقوم مقام صحيفة الدعوى فليس مطلوبا إعلانه إلى المحكوم عليه. ولذلك يمكن القول بسهولة أن هذا الطلب لا تنشأ عنه خصومة، وإنما هو ينتمي إلى نظام العريضة والأوامر على عرائض. ويؤيد هذا التصور أن القرار الصادر في الطلب ليس حكما قضائيا وإنما مجرد أمر قضائي، وأن وسيلة مراجعته هي التظلم وليس الطعن."},{"kind":"text","text":"ورغم اعترافنا بأن هذه الحقيقة هي المستفادة من ظاهر النصوص، إلا أنها قابلة للتشكيك. إذ يستفاد من نص المادة 55 تحكيم أنه من حق المحكوم عليه أن يثير أسباب البطلان في الحكم أثناء نظر طلب المصادقة. ومن لوازم هذا الحق أن يتم إعلان هذا المحكوم عليه بالطلب. فبغير ذلك لن يستطيع التمسك بالبطلان أو إثبات سببه، ذلك البطلان الذي يمكن أن يفضي إلى رفض طلب المصادقة. لن يكون مستغربا إذا في ظل هذا التحليل، القول بأنه يجب أن تنشأ عن طلب المصادقة خصومة قضائية."},{"kind":"text","text":"ولذلك لن يستقيم منطق المشرع إلا إذا أزالت النصوص هذا الغموض وأكدت صراحة على ضرورة إعلان المحكوم عليه بطلب المصادقة حتى يمكنه إبداء أوجه البطلان وإثباتها، رغم أن النظام المتبع هو نظام العريضة. وإلى أن يتدخل المشرع، فإن القاضي المختص بالمصادقة مدعو إلى التحقق من حصول الإعلان وأن يأخذ في الاعتبار أوجه البطلان التي يقدمها المحكوم عليه."},{"kind":"text","text":"ثالثا: نظر الطلب"},{"kind":"text","text":"128- حدد المشرع المهلة التي يجب خلالها صدور القرار بشأن طلب المصادقة، وهي ستون يوما من تاريخ تقديمه (مادة 2- 55 تحكيم). وهي على أي حال مهلة تنظيمية لم يرتب المشرع أي جزاء على تجاوزها."},{"kind":"text","text":"والأصل أن يأمر القاضي بالمصادقة على حكم التحكيم وتنفيذه إلا إذا وجدا سببا للرفض. ويقصد بذلك وجود سبب أو أكثر من أسباب بطلان حكم التحكيم، وتحديدا أسباب البطلان التي تبرر رفع دعوى البطلان، والمذكورة في البند (1) من المادة 53 من قانون التحكيم. أما أسباب البطلان الأخرى فليس لها محل عند نظر طلب المصادقة."},{"kind":"heading","text":"المطلب الثاني: القرار الصادر في طلب المصادقة"},{"kind":"text","text":"أولا: طبيعة القرار الصادر في طلب المصادقة"},{"kind":"text","text":"129- إذا تساءلنا عن طبيعة هذا القرار، فيجب أولا أن نستبعده من مجال الأحكام القضائية. صحيح هو يصدر عن قاض إلا أنه لا يصدر في خصومة، وهذه الأخيرة ركن ركين لوجود الحكم القضائي."},{"kind":"text","text":"ولكن هل يجب أن نستبعده أيضا من مجال الأوامر على العرائض؟ الحقيقة أن عدم استعمال النصوص لعبارة الأمر على عريضة صراحة لا يمنع من أننا أمام أمر ينتمي إلى هذه الطائفة من الأوامر القضائية، فهو يصدر من قاض فرد ودون مواجهة ويخضع للتظلم وليس للطعن، وهذه كلها صفات في الأمر على العريضة."},{"kind":"text","text":"ثانيا: التظلم من الأمر"},{"kind":"text","text":"130- \" يجوز التظلم من قرار المحكمة الصادر بتنفيذ حكم التحكيم أو برفض تنفيذه وذلك أمام محكمة الاستئناف المختصة خلال (30) ثلاثين يوما من اليوم التالي للإعلان\" (مادة 57 تحكيم)."},{"kind":"text","text":"واضح من النص السابق أن التظلم جائز لكل من الصادر ضده الأمر أو لمن رفض طلبه بحسب الأحوال. وواضح أيضا أن الواقعة المجرية لميعاد التظلم في الحالتين هي إعلان الأمر. ومن السهل تقبل ذلك عند التظلم ممن صدر ضده الأمر بالتنفيذ. فقد صدر هذا الأمر في غفلة منه، وبالتالي لا يجوز سقوط حقه في التظلم إلا بعد أن ينقضي الوقت المحدد، والذي لا يجب أن يبدأ إلا من الإعلان."},{"kind":"text","text":"ولكن من غير المفهوم أن يجعل النص واقعة الإعلان هي المجرية أيضا لميعاد التظلم ممن رفض طلبه. معنى ذلك أن ميعاد التظلم بالنسبة له يمكن أن يكون ممتدا بلا نهاية. فالفرض أن الطرف الآخر لا يعلم بصدور قرار الرفض ولا يقوم بالتالي بإعلانه."},{"kind":"text","text":"والتظلم كما هو القاعدة في التقاضي إنما يكون بصحيفة دعوى تعلن إلى المدعى عليه وتنشأ عنه خصومة قضائية بمعنى الكلمة، والقرار الصادر فيها بتأييد الأمر أو إلغائه أو تعديله إنما هو حكم قضائي. هذا الحكم يصدر في حالتنا هذه من محكمة الاستئناف- فهي المحكمة المختصة بالتظلم- ولذلك لا يوجد ما يمنع من الطعن عليه بعد ذلك بالنقض، تطبيقا للقواعد المنظمة للطعن في الحكم الصادر من محكمة الاستئناف في التظلم من الأمر على العريضة."},{"kind":"text","text":"ثالثا: وقف تنفيذ الأمر"},{"kind":"text","text":"131- الفرض الآن أن القرار الصادر في طلب المصادقة كان صادرا بالموافقة، أي بتنفيذ حكم التحكيم. ولأنه أمر على عريضة، فإن قابليته للتظلم لا تمنع من تنفيذه، فهو مشمول بالنفاذ المعجل بقوة القانون تطبيقا للمادة 1-215 – د."},{"kind":"text","text":"ولكن هل يمكن وقف تنفيذ هذا القرار بمناسبة التظلم منه؟ الواقع أنه رغم عدم وجود نص في قانون التحكيم، إلا أننا نرى أنه يجوز لمحكمة التظلم أن تحكم بوقف التنفيذ لحين الفصل في التظلم، على أن يكون ذلك بناء على طلب المتظلم، والذي عليه أن يثبت الخشية من وقوع ضرر جسيم من التنفيذ. وكل ذلك يعتبر تطبيقا للقواعد العامة، خاصة تلك المقررة في المادة 1- 221 من قانون الإجراءات."},{"kind":"heading","text":"المطلب الثالث: وقف تنفيذ حكم المحكم ذاته"},{"kind":"text","text":"132- يوجد محل للحديث عن وقف تنفيذ حكم المحكم ذاته بعد أن يكون سندا تنفيذيا، أي بعد أن يصدر الأمر بالمصادقة عليه. أما قبل ذلك فالمفروض أنه ليست لحكم المحكم أيه قوة تنفيذية، وبالتالي ليس مقبولا من حيث المبدأالحديث عن وقف تنفيذه. ومع ذلك تتناول النصوص التي تتكلم عن دعوى بطلان حكم المحكم جواز الحكم بوقف تنفيذه، بناء على طلب أحد الأطراف- هو المحكوم عليه عادة- إذا كان الطلب مبنيا على أسباب جدية (مادة 56 تحكيم). ولم يفترض النص في الحكم المطلوب وقف تنفيذه أنه قد تمت المصادقة. فهل معنى ذلك جواز قبول طلب الوقف حتى قبل المصادقة؟"},{"kind":"text","text":"من الواضح أن النص يسمح بذلك. ويجد هذا الحل مبرره في أن المصلحة المحتملة تكفي لقبول الطلب طبقا للمادة الثانية من قانون الإجراءات. هذه المصلحة تتمثل في الاحتياط لدفع ضرر محدق هو احتمالية صدور قرار المصادقة في أي وقت أثناء نظر دعوى البطلان."},{"kind":"text","text":"وطلب الوقف هذا يعد طلبا مستعجلا بطبيعته. ولذلك كان منطقيا أن يتطلب المشرع نظره على وجه السرعة. وبالفعل تقرر المادة 2- 56 من قانون التحكيم أن على المحكمة الفصل في طلب وقف التنفيذ خلال (15) خمسة عشر يوما من تاريخ أول جلسة محددة لنظره. هذا مع الأخذ في الاعتبار أن هذا الميعاد هو ميعاد تنظيمي لا يترتب أي جزاء على مخالفته. نفس الملاحظة تنطبق أيضا على ميعاد الستين يوما الذي يجب على المحكمة أن تصدر خلاله حكمها في دعوى البطلان إذا كانت قد حكمت بوقف التنفيذ (مادة 3- 57 تحكيم)."},{"kind":"heading","text":"المبحث الخامس: المحررات الموثقة"},{"kind":"text","text":"133- تعدد المادة 2- 212- السندات التنفيذية، وتذكر من بينها \"المحررات الموثقة طبقا للقانون المنظم للتوثيق والتصديق\". وعادة ما يسمى هذا القانون بالقانون المنظم للكاتب العدل، على أساس أن هذا الأخير هو الموظف المختص بالتوثيق والتصديق."},{"kind":"text","text":"والحقيقة أن المحررات التي تصدر عن الكاتب العدل متنوعة. فهناك على الأقل ثلاثة: المحررات الموثقة والمحررات المصدقة والمحررات التي يتم إثبات تاريخها. ولكن لن تدخل كل هذه المحررات في مجال السند التنفيذي، وإنما يقتصر الأمر فقط - وكما هو واضح من المادة آنفة الذكر- على واحدة منها هي المحررات الموثقة. فالمحرر الموثق بالمعنى الفني الدقيق يعتبر سندا تنفيذيا، ويستطيع الدائن بموجب صورته التنفيذية أن يطلب من قاضي التنفيذ تنفيذ الالتزامات الثابتة به جبرا. من الواضح إذا أن المحرر الموثق لا يجعل الدائن في حاجة إلى الالتجاء إلى القضاء للحصول على حكم أو أمر قضائي ليكون هو السند التنفيذي."},{"kind":"text","text":"134- واختيار المشرع للمحرر الموثق دون غيره من أعمال الكاتب العدل لكي يكون سندا تنفيذيا، راجع إلى الثقة الكبيرة التي تتوافر في الموثق وفي عملية التوثيق ذاتها. فالمحرر الموثق هو السند أو العقد الذي يقوم الكاتب العدل بتحريره- أي بإنشائه أو كتابته- بنفسه، وكذلك التصديق عليه- حسب طلب ذوي الشأن، بعد التأكد من هويتهم وتوافر السلطة القانونية لديهم في إبرامه، وكذلك رضائهم وتوقيعاتهم، وعدم وجود مخالفة للنظام العام أو التشريعات السارية. من الواجب إذا فهم عبارة المحرر الموثق الذي يعتبر سندا تنفيذيا بالمعنى السابق توضيحه، أي الذي يقوم فيه الكاتب العدل بعمل مزدوج هو التحرير والتصديق، وبصرف النظر عن التسمية الملتبسة التي قد تطلق عليه. فبعض التشريعات في الدولة تستعمل عبارة المحررات الموثقة في معناها الفني الدقيق، بينما يستعمل بعضها الآخر عبارة \"المحررات المحررة\" للدلالة على هذه المحررات الموثقة."},{"kind":"text","text":"135- وبصرف النظر عن العبارة الدالة، فإن الثقة التي تتوافر في المحرر الموثق لا تتوافر بنفس الدرجة في المحررات الأخرى الصادرة من الكاتب العدل. ولذلك لم تدخلها التشريعات ضمن السندات التنفيذية. نقصد بذلك تحديدا المحررات العرفية المصدقة، أو التي يجرى إثبات تاريخها. ولذلك لا يجب وضع الصيغة التنفيذية على المحررات الأخرى هذه لعدم دخولها في عداد السندات التنفيذية. ومن باب أولى لا تعتبر المحررات الرسمية الصادرة عن غير الكاتب العدل سندات تنفيذية. ينطبق ذلك مثلا على محاضر الشرطة أو النيابة، ووثائق الزواج التي يحررها المأذونون. أيضا لا تعتبر المحررات المسجلة سندات تنفيذية طالما أنها ليست موثقة بواسطة الكاتب العدل."},{"kind":"heading","text":"المبحث السادس: السندات التنفيذية الأخرى"},{"kind":"text","text":"136- بعد أن عددت المادة 2-212 السندات التنفيذية المسماة -إن جاز التعبير-، ذكرت أنه من السندات التنفيذية أيضا \"الأوراق الأخرى التي يعطيها القانون هذه الصفة\". معنى ذلك أن السندات التنفيذية المذكورة أنفا في هذه المادة ليست على سبيل الحصر، وأنه يمكن لورقة أخرى أن تحمل اسم السند التنفيذي، شريطة أن يوجد نص في القانون- أي قانون- يعطيها هذه الصفة. وليس بالضرورة أن النص الذي يعطي هذه الصفة يقرر في عبارة صريحة أن هذه الورقة أو تلك تعتبر سندا تنفيذيا، بل يكفي أية عبارة تحمل هذا المعنى. فيكفي مثلا أن يقرر النص أن ورقة ما تكون لها القوة التنفيذية، أو تكون في قوة السند التنفيذي، أو تنفذ كما تنفذ الأحكام."},{"kind":"text","text":"وقد سبق لنا التعرض لبعض الأوراق الأخرى التي يعطيها القانون صفة السند التنفيذي، وهو ما ينطبق على ما سبق بحثه من حكم المحكم وبعض محاضر الصلح التي يصدق عليها القاضي المختص في غير خصومة. ونتعرض الآن لأوراق أخرى هي: الشيك، وقرار الغرامة الثابت في محضر الجلسة، ومحضر التحقيق الذي يتضمن تعهدا بدفع مبلغ الضمان."},{"kind":"heading","text":"المطلب الأول: الشيك (المرتجع أو المرتد)"},{"kind":"text","text":"137- لم يكن الشيك المرتجع سندا تنفيذيا قبل التعديلات الأخيرة التي طرأت على قانون المعاملات التجارية السابق، والتي تأكدت في قانون المعاملات التجارية الحالي. فقط كان بالإمكان استصدار أمر أداء بالاستناد إليه. والوضع الآن، ووفقا للمادة 1-667من قانون المعاملات التجارية الحالي \" يعد الشيك المثبت عليه من قبل المسحوب عليه بعدم وجود رصيد له أو عدم كفايته سندا تنفيذيا.. ولحامله طلب تنفيذه كليا أو جزئيا جبرا..\"."},{"kind":"text","text":"بناء على هذا النص، لم تعد هناك حاجة لحامل الشيك إلى استصدار أمر أداء أو رفع دعوى أو اتخاذ أي اجراء قضائي آخر. فالآن صار الشيك سندا تنفيذيا يجيز لحامله اللجوء إلى قاضي التنفيذ مباشرة للتنفيذ بقيمته أو المتبقي منها. فكل ما هو مطلوب هو تأشير البنك المسحوب عليه على ظهر الشيك بعدم وجود رصيد وإعطاء حامل الشيك شهادة بما يفيد ذلك."},{"kind":"text","text":"138- وتتبع في تنفيذ هذا الشيك بعد ذلك إجراءات التنفيذ التي نص عليها قانون الإجراءات المدنية، والمتبعة بشأن سائر السندات التنفيذية. يستوي في كل ذلك أن يكون التنفيذ في مواجهة الساحب أو في مواجهة أي من الموقعين على الشيك، كالمظهر مثلا."},{"kind":"text","text":"139- أخيرا يلاحظ أنه بالنسبة للشيك المرتجع لأن الحساب الجاري مغلق، فهذا معناه أنه لا يوجد رصيد قابل للسحب، وبالتالي يعتبر شيكا بلا رصيد."},{"kind":"text","text":"وإذا لم يتقبل قضاء التنفيذ هذا التفسير، فليس أمام المستفيد سوى اللجوء إلى قاضي الأداء، واستصدار أمر أداء يكون هو سند التنفيذ."},{"kind":"heading","text":"المطلب الثاني: قرار الغرامة الثابت في محضر الجلسة"},{"kind":"text","text":"140- يتناول نص المادة 74 قرار المحكمة أو القاضي المشرف والثابت في محضر الجلسة، بتوقيع غرامة على من يتخلف من العاملين بالمحكمة أو من الخصوم عن إيداع المستندات أو عن القيام بأي إجراء من إجراءات الدعوى في الميعاد. ويعطي النص المذكور صفة السند التنفيذي لهذا القرار، وذلك من خلال ذكر أن له ما للأحكام من قوة تنفيذية"},{"kind":"text","text":"هذا القرار ليس أمرا على عريضة، وإن كان يعد عملا ولائيا مثله، ويدخل بالتالي في طائفة الأوامر القضائية. وهو بصريح نص المادة المذكورة لا يقبل الطعن عليه بأي طريق، ولذلك يقبل التنفيذ الجبري فور صدوره. ولا يغير من ذلك قابليته للتظلم. يستفاد وجود طريق المراجعة هذا من أنه للمحكمة أو القاضي المشرف بحسب الأحوال - وبصريح نفس المادة - أن يقيل الصادر ضده القرار (أسماه النص تجاوزا المحكوم عليه) من الغرامة كلها أو بعضها إذا أبدى عذرا مقبولا، وبطريق اللزوم العقلي، لن يتمكن الصادر ضده القرار من إبداء العذر ويحصل على الإقالة من الغرامة، إلا لو قدم تظلما."},{"kind":"text","text":"وتجب ملاحظة أنه طالما لم تحدث إقالة من الغرامة بناء على التظلم، فالحق الثابت في القرار يعد محقق الوجود."},{"kind":"heading","text":"المطلب الثالث: محضر التحقيق الذي يتضمن تعهدا بدفع مبلغ الضمان"},{"kind":"text","text":"141- وفقا للمادة 109 من قانون الإجراءات الجزائية، للنيابة العامة أن تعلق قرارها بالإفراج المؤقت عن المتهم المحبوس احتياطيا على تقديم ضمان مالي، ووفقا للمادة 110 من ذات القانون، يكون لمحضر التحقيق أو التقرير في مكتب إدارة الدعوى الذي يتضمن تعهدا من شخص مليء بدفع المبلغ المقدر للضمان إذا أخل المتهم بشروط الإفراج، قوة السند التنفيذي."},{"kind":"heading","text":"المبحث السابع: شروط استعمال السند التنفيذي"},{"kind":"text","text":"146- إذا كان الحق في التنفيذ الجبري ينشأ عن السند التنفيذي، إلا أن استعمال هذا الحق يتطلب شروطا أخرى تتعلق بهذا السند ذاته. فهناك شرط شكلي هو أن يأخذ السند التنفيذي شكلا معينا هو شكل الصورة التنفيذية، وهناك شروط موضوعية يجب توافرها في الحق الثابت في هذا السند."},{"kind":"text","text":"وبناء عليه، سوف تتوزع الدراسة في هذا المبحث بين مطلبين، نخصص الأول منهما للصورة التنفيذية، ونخصص الثاني لشروط الحق الثابت في السند التنفيذي."},{"kind":"heading","text":"المطلب الأول: الصورة التنفيذية"},{"kind":"text","text":"تمهيد وتقسيم"},{"kind":"text","text":"147- إن عبارة الصورة التنفيذية ليست مرادفا لعبارة السند التنفيذي، رغم أن هذا الأخير لا يختلف كثيرا عن هذه الصورة. فلماذا إذا يتطلبها المشرع ولا يكتفي بالسند ذاته. من الضروري إذا الوقوف على حقيقة الصورة التنفيذية والحكمة منها (الفرع الأول). ولأن الحكم القضائي وهو أشهر السندات التنفيذية، قد يكون مركبا من حكمين- كما لو كان مركبا من الحكم الابتدائي والحكم الاستئنافي الذي صدر بالتأييد- حتى يستجمع مقومات السند التنفيذي، فإنه يكون واجبا على هذه الدراسة المخصصة للصورة التنفيذية تحديد الحكم القضائي الذي ستوضع عليه الصيغة التنفيذية (الفرع الثاني). وقد يحدث أن يتعذر-للفقد مثلا- استعمال الصورة التنفيذية المسلمة للمستفيد منها. ولذلك يجب التعرف على كيفية تسليمه صورة تنفيذية ثانية (الفرع الثالث). وأخيرا يجب الوقوف على الحالات الاستثنائية التي يجيز فيها المشرع التنفيذ بغير الصورة التنفيذية (الفرع الرابع)."},{"kind":"text","text":"الفرع الأول: ماهية الصورة التنفيذية والحكمة منها"},{"kind":"text","text":"148- ينشأ الحق في التنفيذ الجبري بمجرد نشأة السند التنفيذي، وهو ورقة من الأوراق التي أعطاها القانون هذه الصفة، كالحكم القضائي وغيره مما سبق دراسته. لكن لن يكون في مكنة صاحب هذا الحق استعمال سنده وتحريك سلطة التنفيذ لمجرد أنه يحوز نسخة ولو أصلية منه، وإنما يجب أن تكون هذه النسخة قد أخذت شكلا معينا هو شكل \"الصورة التنفيذية\"."},{"kind":"text","text":"ويقصد بالصورة التنفيذية صورة طبق الأصل من السند التنفيذي، كل ما هنالك أن عليها \"الصيغة التنفيذية\". ويقصد بهذه الأخيرة، عبارة معينة ذكرها المشرع تفيد وجود واجب على سلطة التنفيذ القيام به."},{"kind":"text","text":"كل ما سبق يجد أساسه التشريعي في البند 3 من نص المادة 212 والتي تقرر أنه \"لا يجوز التنفيذ.. إلا بموجب صورة من السند التنفيذي عليها صيغة التنفيذ..\"."},{"kind":"text","text":"وبناء عليه، فالصورة التنفيذية للحكم القضائي مثلا التي لا يصح التنفيذ إلا بموجبها، هي نسخة مصدقة من الحكم، وعليها أيضا توقيع الموظف المختص بوضع الصيغة التنفيذية، بعد أن يذيلها بها (مادة 1- 131). أما الصورة التنفيذية لأمر الأداء، فهي إحدى نسخ العريضة، والتي كتب عليها الأمر ووقع عليه القاضي الذي أصدره، ووضعت عليها الصيغة التنفيذية. أما فيما يتعلق بالمحرر الموثق، فإن صورته التنفيذية هي صورة المحرر التي يوقعها الموثق بعد أن يذيلها بالصيغة التنفيذية. وهكذا الحال بالنسبة لكل سند تنفيذي."},{"kind":"text","text":"149- ولقد كان رائد المشرع عندما تطلب الصورة التنفيذية هو تحقيق مصلحة مزدوجة لكل من طالب التنفيذ والمنفذ ضده. فبالنسبة لطالب التنفيذ، يعتبر وضع الصيغة التنفيذية على السند دليلا قطعيا- وظاهرا - على أنه سند تنفيذي، وأن الثابت اسمه في هذا السند هو صاحب حق في التنفيذ، بحيث لا يجد أي ممانعة من جانب سلطة التنفيذ في إنفاذه. وبالنسبة للمنفذ ضده، فإن الصورة التنفيذية تحميه من الخضوع لتنفيذ جائر. فالمشرع يشترط لوضع الصيغة التنفيذية على الحكم القضائي مثلا \"أن يكون جائز التنفيذ\" (مادة 1- 131). كما تحميه الصورة التنفيذية أيضا من الخضوع لتنفيذ متكرر. إذ الصورة التنفيذية صورة واحدة لا تتعدد، وعندما يتم تنفيذها فإن ذلك يظهر عليها، فيمتنع تنفيذها من جديد. بعكس لو كان ممكنا التنفيذ بنسخة السند التنفيذي ذاتها، إذ لا يمكن أحيانا حصرها في نسخة وحيدة."},{"kind":"text","text":"الفرع الثاني: تحديد الحكم القضائي الذي ستوضع عليه الصيغة التنفيذية"},{"kind":"text","text":"150- لأن الحكم القضائي هو أشهر السندات التنفيذية، وهو عرضة لتقلبات عدة، فقد يطعن عليه فيصدر حكم جديد بتأييد الأول أو بإلغائه، ثم يتم الطعن في الحكم الثاني ويتم إلغاؤه ويعود الحكم الأول إلى الوجود. لذلك كان من الضروري تحديد نسخة الحكم التي ستوضع عليها الصيغة التنفيذية، وذلك في عدة فروض:"},{"kind":"text","text":"151- (1) الفرض الأول، الحكم في الأصل كان ابتدائيا ثم صار نهائيا بعد أن أصبح غير قابل للاستئناف. إشكالية هذا الفرض أن ورقة الحكم المطلوب وضع الصيغة عليها تفيد أنه حكم ابتدائي، وبالتالي لا تتوافر فيه صفة السند التنفيذي، رغم أن هذا الحكم صار نهائيا، ولكن الدليل على ذلك مستمد من مصدر خارج عن الحكم. ولذلك يجب أولا الحصول من محكمة الاستئناف على شهادة بعدم حصول استئناف أو الحكم بعدم قبوله أو بسقوطه، ثم التقدم بذلك- وهو ما يثبت النهائية- إلى محكمة أول درجة للحصول على الصورة التنفيذية للحكم الذي صدر منها."},{"kind":"text","text":"152- (2) الفرض الثاني، الحكم في الأصل كان ابتدائيا وغير مشمول بالنفاذ المعجل، ثم اتفق أطرافه على شموله بهذا النفاذ بعد صدوره. هذا الحكم يصلح إذا لكي يكون سندا تنفيذيا. ولذلك يجوز تقديم ما يفيد هذا الاتفاق إلى المحكمة التي أصدرت الحكم لكي تضع عليه الصيغة التنفيذية. ومع ذلك يصعب من الناحية العملية الاعتداد بهذا الاتفاق للتسريع بوضع الصيغة التنفيذية. لذلك فإن المعول عليه في التنفيذ هنا هو التنفيذ الاختياري وليس الجبري."},{"kind":"text","text":"153- (3) الفرض الثالث، حكم الاستئناف صدر بمنطوق مقتضب، هو تأييد حكم أول درجة ولأسبابه. الإشكال المثار هنا هو أن حكم أول درجة هذا هو الدال على الأداء المطلوب، إلا أنه ليس سندا تنفيذيا لكونه حكما ابتدائيا. وفي ذات الوقت لا يمكن الاكتفاء بحكم الاستئناف كسند تنفيذي رغم أنه حكم نهائي، نظرا لأن منطوقه غير دال على الأداء المطلوب من المحكوم عليه. لم يعد بد إذا من الاعتماد على الحكمين معا. على أن يكون الموظف المختص بمحكمة الاستئناف هو المنوط به وضع الصيغة التنفيذية على الحكم الصادر منها، مرفقا به الحكم الابتدائي. ولا مانع من ذكر عبارة تدل على أن هذا الإرفاق لغايات إعطاء الصورة التنفيذية. ومما يعزز هذا الحل من الناحية الواقعية، أن ملف الدعوى قد انتقل منذ رفع الطعن إلى محكمة الاستئناف وصار في حوزتها."},{"kind":"text","text":"154- (4) الفرض الرابع، حكم الاستئناف قد اكتفى بإلغاء الحكم الابتدائي. والأصل أن حكم الاستئناف هذا يعتبر حكما تقريريا ولا يحتاج بالتالي إلى تنفيذ، ومن ثم لا مبرر لكي تثور بصدده مسألة الصيغة التنفيذية والموظف المختص بوضعها."},{"kind":"text","text":"لكن يرد على هذا الأصل استثناء يتعلق بالفرض الذي يكون فيه الحكم الابتدائي الملغي مشمولا بالنفاذ المعجل وتم تنفيذه. هنا سيكون حكم الإلغاء الصادر من محكمة الاستئناف متضمنا أيضا حكم إلزام ضمني بإعادة الحال إلى ما كان عليه قبل إجراء التنفيذ المعجل. فلو كان قد سبق سداد مبلغ التعويض مثلا، فالمطلوب الآن استرداد هذا المبلغ ولو جبرا. سوف يكون حكم الإلغاء في هذه الحالة سندا تنفيذيا لاسترداد المبلغ، ومن ثم يحتاج إلى وضع صيغة تنفيذية عليه. والموظف المختص بطبيعة الحال هنا هو التابع لمحكمة الاستئناف."},{"kind":"text","text":"155- (5) الفرض الخامس، حكم الاستئناف لم يكتف بإلغاء الحكم الابتدائي، وإنما فصل أيضا في الموضوع من جديد. ليس هناك شك في أن حكم الاستئناف الموضوعي هذا سيكون هو السند التنفيذي والذي ستوضع عليه الصيغة التنفيذية."},{"kind":"text","text":"156- (6) الفرض السادس، حكم النقض (أو التمييز) ألغى حكم الاستئناف الذي سبق تنفيذه. وتثور بهذه المناسبة مسألة أن حكم النقض يعتبر سندا تنفيذيا لإعادة الحال إلى ما كان عليه. ونرى أنه ينطبق هنا حل مماثل للحل الذي رأيناه بالنسبة للاستثناء الوارد في الفرض الخامس، على أن يكون الموظف المختص هنا، هو التابع للمحكمة العليا."},{"kind":"text","text":"157- (7) الفرض السابع، حكم النقض (أو التمييز) ألغى حكم الاستئناف، وهذا الأخير كان قد ألغى حكما ابتدائيا مشمولا بالنفاذ المعجل. هنا سيعود الحكم الأخير إلى الوجود ليكون هو السند التنفيذي، والمفروض أن الصيغة التنفيذية كانت عليه من قبل."},{"kind":"text","text":"158- (8) الفرض الثامن، حكم النقض (أو التمييز) فصل في الموضوع. لا شك في أن هذا الحكم- وعلى فرض أنه صادر بإلزام- سيكون هو السند التنفيذي، والذي ستوضع عليه الصيغة التنفيذية، بواسطة الموظف المختص في المحكمة العليا الصادر عنها هذا الحكم."},{"kind":"text","text":"159- (9) الحكم الصادر في الموضوع من محكمة الطعن بالتماس إعادة النظر، أيا كانت هذه المحكمة، ولو كانت المحكمة العليا. لا شك أن هذا الحكم- وعلى فرض أنه كان صادرا بإلزام- سيعتبر سندا تنفيذيا، ومن ثم ستوضع عليه الصيغة التنفيذية بواسطة الموظف المختص في المحكمة التي أصدرته."},{"kind":"text","text":"الفرع الرابع: حالات جواز التنفيذ بغير الصورة التنفيذية"},{"kind":"text","text":"163- \"لا يجوز التنفيذ- في غير الأحوال المستثناة بنص في القانون- إلا بموجب صورة من السند التنفيذي عليها صيغة التنفيذ..\" (مادة 3- 212). واضح من هذا النص أن قاعدة وجوب الصورة التنفيذية لاستعمال الحق في التنفيذ ليست قاعدة مطلقة، وأنه يمكن أن يرد عليها استثناءات. وبالفعل تتضمن النصوص أحوالا يجوز فيها التنفيذ بغير الصورة التنفيذية."},{"kind":"text","text":"الحكمة من هذه الاستثناءات عادة هو عامل السرعة. فرغم أن الحصول على الصورة التنفيذية للسند التنفيذي تستغرق عادة وقتا قصيرا، إلا أن طالب التنفيذ قد يكون في حاجة إلى حماية تنفيذية سريعة في بعض الأحوال لا تحتمل الانتظار ولو ليوم واحد. عندئذ يكون من المناسب أن يضحي المشرع بالمصلحة التي تحققها الصورة التنفيذية بالنسبة للمدين، ويعفي الدائن من قاعدة ضرورة الصورة التنفيذية. وقد يكون عنصر المفاجأة هو الذي يجعل المشرع يلجأ إلى الاستثناء. فعندما يكون البدء في التنفيذ بغتة سلوكا جائزا حتى لا يهرب المدين أمواله، فإنه بالتناغم مع ذلك يعفي المشرع الدائن من اتخاذ مقدمات التنفيذ المعروفة، وكذلك من ضرورة الحصول على صورة تنفيذية لسنده."},{"kind":"text","text":"والاستثناءات يجب أن تكون مقررة قانونا. وإذا تأملناها وجدناها تنقسم إلى قسمين. القسم الأول هو حالات يجوز فيها التنفيذ بغير الصورة بقوة القانون، والقسم الثاني هو حالات يجوز فيها التنفيذ بغير الصورة بشرط أن تقرر المحكمة ذلك."},{"kind":"heading","text":"1- الاستثناءات المقررة بحكم القانون"},{"kind":"text","text":"164- التنفيذ بغير الصورة التنفيذية جائز بقوة القانون في حالة شهيرة هي أن يكون السند التنفيذي أمرا على عريضة. فالمادة 3-140 صريحة في أن هذا الأمر ينفذ \"دون الحاجة إلى.. صيغة تنفيذية\"، مما مفاده الإعفاء بحكم القانون من الصورة التنفيذية. وتجب ملاحظة مدى اتساع هذه الحالة. يكفي أن الأمر على عريضة هو السند الوحيد الواجب توافره لاتخاذ بعض الإجراءات التحفظية- وهي من أعمال التنفيذ الجبري- وتحديدا الحجز التحفظي أو حجز ما للمدين لدى الغير أو أمر المنع من السفر أو حبس المدين."},{"kind":"heading","text":"2- الاستثناءات المقررة بحكم القضاء"},{"kind":"text","text":"165- \"يجوز للمحكمة في المواد المستعجلة أو في الأحوال التي يكون فيها التأخير ضارا، أن تأمر- بناء على طلب ذي الشأن- بتنفيذ الحكم.. بغير وضع صيغة تنفيذية عليه\" (مادة 3-212). الملاحظة الأولى على هذا النص، أنه الوحيد المتضمن للأحوال التي يجوز فيها للقضاء الأمر بالتنفيذ بغير الصورة التنفيذية. ليس للقضاء إذا أن يأمر بالتنفيذ بغير الصورة التنفيذية في أي حالة، وإنما فقط في الأحوال المحددة في هذا النص. والملاحظة الثانية، أن مجال عمل هذه الأحوال هو فقط الحكم القضائي. أي أنه إذا كان السند التنفيذي حكما قضائيا، فعندئذ قد يوجد مجال لجواز الأمر بتنفيذه بغير الصورة التنفيذية. أما باقي السندات التنفيذية- حتى لو كانت تصدر من القضاء- لا يجوز للمحكمة أن تأمر بتنفيذ أي منها بغير الصورة التنفيذية."},{"kind":"text","text":"166- الفرض الآن إذا أننا أمام دعوى قضائية نشأت عنها خصومة، وسوف يصدر في موضوعها حكم قضائي مما ينطبق عليه وصف السند التنفيذي. ووفقا للقاعدة العامة، لن يكون للمحكوم له الحق في استعمال هذا الحكم إلا بعد إكساء نسخة هذا الحكم بالصيغة التنفيذية، وهو ما يستغرق وقتا. ولذلك أعطاه المشرع منذ وقت مبكر- وقبل صدور الحكم- الحق في أن يطلب من المحكمة التي تنظر دعواه أن تصدر حكمها هذا مشفوعا بجواز تنفيذه بغير الصورة التنفيذية. فإذا توافرت إحدى الحالات التي تبرر ذلك، وكانت المحكمة قد استجابت لطلبه هذا، كان بإمكانه أن يشرع في طلب التنفيذ فور تحصله على مجرد النسخة المصدقة من الحكم."},{"kind":"text","text":"واضح مما سبق، أن هناك ثلاثة شروط لصدور الأمر القضائي بالتنفيذ بغير الصورة التنفيذية:"},{"kind":"heading","text":"167- الشرط الأول: أن تتوافر حالة من حالات الإعفاء القضائي من الصورة التنفيذية"},{"kind":"text","text":"تتضمن المادة 3-212 حالتين يملك فيهما القاضي الإعفاء، أولاهما أن يكون الحكم مستعجلا، وثانيهما أن يكون الحكم موضوعيا إلا أن التأخير يكون ضارا بالمحكوم له."},{"kind":"text","text":"فالحالة الأولى، أن تكون الدعوى مستعجلة أيا كانت المحكمة التي تنظرها. أي سواء كانت قاضي الأمور المستعجلة أم محكمة الموضوع حين تكون مختصة بهذه الدعوى بالتبعية للدعوى الموضوعية المرفوعة أمامها. ولا شك أن حالة الاستعجال التي تحيط بهذه الدعوى تظل عادة متوافرة حتى بعد صدور الحكم فيها، مما يجعل هذا الأخير مستحقا للتنفيذ فور صدوره، وبالتالي يتوافر أثناء نظر الدعوى مبرر مقبول لطلب تنفيذه بغير إبطاء، ومن ثم بغير الصورة التنفيذية. لذلك كان من المنطقي أن يجعل المشرع الحالة محل البحث ضمن حالات الإعفاء القضائي من الصورة التنفيذية، وعلى فرض توافر باقي الشروط."},{"kind":"text","text":"أما الحالة الثانية، فهي أن تكون الدعوى موضوعية. والأصل أن الحكم الصادر في هذه الدعوى يخضع للقاعدة العامة وهي ضرورة الصورة التنفيذية. إلا أنه إذا استطاع المحكوم له أن يثبت للمحكمة أثناء نظر الدعوى أنه في حاجة إلى حماية تنفيذية سريعة، مدللا على ذلك بأن ضررا سوف يصيبه لو توجب عليه انتظار الصورة التنفيذية، فعندئذ يمكن القول بوجود الحالة الثانية من حالات الإعفاء القضائي من الصورة التنفيذية. إذ يحق للمحكمة هنا التصريح بتنفيذ الحكم بمقتضى نسخته المصدقة، والتي يمكن الحصول عليها فور إصداره، ودون حاجة إلى إعداد الصورة التنفيذية."},{"kind":"heading","text":"168- الشرط الثاني: تقديم الطلب"},{"kind":"text","text":"اتساقا مع مبدأ الطلب وأنه لا يجوز للمحكمة أن تحكم بشيء لم يطلبه الخصوم، كان منطقيا أن تعلق المادة 3-212 الإعفاء القضائي من الصورة التنفيذية في الحالتين المشار إليهما في الشرط الأول على تقديم طلب بذلك من ذوي الشأن. ويقصد بذوي الشأن هنا صاحب المصلحة من الخصوم، وهو عادة المدعي مقدم الطلب القضائي والراغب في إصدار حكم فيه لصالحه. وطبقا للقواعد العامة يجوز طلب الإعفاء من الصورة التنفيذية إما في صحيفة الدعوى عند رفعها وإما في وقت لاحق أثناء نظرها. وبطبيعة الحال لا يقبل هذا الطلب بعد صدور الحكم واستنفاد المحكمة بالتالي لولايتها."},{"kind":"heading","text":"169- الشرط الثالث: الأمر بالتنفيذ بغير الصورة التنفيذية"},{"kind":"text","text":"لا يكفي توافر حالة من حالات الإعفاء من الصورة التنفيذية وتقديم طلب بذلك، وإنما يجب أيضا أن تستجيب المحكمة لهذا الطلب وتأمر بالتنفيذ بغير الصورة. وقد بدأت عبارة المادة 213 المنظمة لهذا الأمر بكلمة \"يجوز للمحكمة\"، مما مفاده أنها أعطت للمحكمة سلطة تقديرية في هذا الشأن، وبالتالي لا تثريب عليها إن رفضت إصدار الأمر حتى ولو توافرت باقي الشروط."},{"kind":"text","text":"والجدير بالذكر أن الأمر الصادر من المحكمة بالاستجابة للطلب أو برفضه هو في حقيقته حكم قضائي صادر في طلب- وإن كان طلبا إجرائيا- وليس عملا ولائيا، رغم عبارة \"تأمر\" الواردة في النص. وبناء عليه يقبل هذا الحكم الطعن عليه وفقا للقواعد العامة للطعن في الحكم الإجرائي."},{"kind":"text","text":"الفرع الثالث: كيفية تسليم صورة تنفيذية ثانية"},{"kind":"text","text":"160- القاعدة كما سبق وقلنا هي أنه يمكن تعدد نسخ السند التنفيذي ولا يمكن التنفيذ بأي منها، بينما لا توجد له سوى صورة تنفيذية واحدة، وهي التي يمكن التنفيذ بموجبها."},{"kind":"text","text":"هذه الصورة قد تضيع من صاحبها أو تتلف، فيتعذر بالتالي استعمال الحق في التنفيذ رغم وجوده. ولذلك كان على المشرع مواجهة هذه الفرضية ووضع حل ملائم لها."},{"kind":"text","text":"هذا الحل لن يكون مثاليا إلا إذا سمحنا لصاحب الحق في التنفيذ باستعماله من خلال تسليمه صورة ثانية، وفي نفس الوقت نضمن للمدين عدم خضوعه لتنفيذ متكرر نتيجة حصول الدائن على صورتين. الحل المتوازن إذا هو الذي لا يمنع من تسليم صاحب الحق صورة تنفيذية ثانية- أو حتى ثالثة أو أكثر- طالما ثبت عدم سبق التنفيذ بالصورة الأولى."},{"kind":"text","text":"161- وبالفعل يقنن المشرع الحل بمناسبة الحكم القضائي، وهو أكثر السندات التنفيذية شيوعا. فقد سمح بتسليم صورة تنفيذية ثانية للحكم القضائي لذات الخصم عند فقد الصورة الأولى أو تعذر استعمالها، ويكون ذلك بأمر من المحكمة (مادة 2-131)."},{"kind":"text","text":"وإذا كان يحمد لهذا الحل السماح بتسليم صورة ثانية بإجراءات مبسطة، إلا أن الوصول إليه من خلال نظام الأوامر على عرائض لا يخلو من نقد. ذلك لأن هذا النظام يفتقد لعنصر المواجهة وبالتالي لا يضمن علم القاضي بعدم سبق التنفيذ. بخلاف الحال لو أن المشرع قد تبنى نظام الدعوى القضائية وما تكفله خصومتها من تمكين الطرف الآخر من إبداء أوجه دفاعه ليصدر القاضي حكمه على ضوئها. ولذلك ندعو المشرع إلى تبني نظام الدعوى إذا أراد المحكوم له الحصول على صورة تنفيذية ثانية."},{"kind":"heading","text":"المطلب الثاني: الشروط الموضوعية للحق الثابت في السند التنفيذي"},{"kind":"text","text":"170- إن دراسة السند التنفيذي كمصدر منشئ للحق في التنفيذ الجبري، لا يجب أن تحجب عنا حقيقة أن هذا السند يتضمن أساسا حقا موضوعيا، هو الذي سيجري التنفيذ لاقتضائه. هذا الحق الموضوعي يجب- من وجهة نظر المشرع- أن يستجمع شروطا معينة، لا مانع من القول بأنها تمثل الشروط الموضوعية للسند التنفيذي ذاته. ويمكن الوقوف على هذه الشروط من خلال المادة 1- 212. فبعد أن نصت المادة المذكورة على عدم جواز التنفيذ الجبري إلا بسند تنفيذي، ذكرت أن هذا التنفيذ يجب أن يكون \"اقتضاء لحق محقق الوجود ومعين المقدار وحال الأداء\"."},{"kind":"text","text":"هذه الشروط الموضوعية يجب توافرها سواء كان التزام المدين هو دفع مبلغ من النقود (وبالتالي كان واجبا التنفيذ بطريق الحجز) أو كان التزاما بعمل أو امتناعا عن عمل (وبالتالي كان واجبا اللجوء إلى التنفيذ المباشر أو العيني)."},{"kind":"text","text":"وهي متوافرة عادة سلفا عندما يكون السند التنفيذي حكما قضائيا. إذ من طبيعة الحكم القضائي القطعي- والأصل أنه كذلك- أنه يحسم النزاع حول وجود الدين أو عدم وجوده وكذلك مقداره."},{"kind":"text","text":"ولذلك فإنه إذا حدث وأثيرت منازعة حول هذه الشروط، فإنها تكون غالبا بمناسبة تنفيذ السندات الأخرى."},{"kind":"text","text":"(1) محقق الوجود"},{"kind":"heading","text":"171- يكون الحق الثابت في السند التنفيذي محقق الوجود إذا كان مؤكدا وليس احتماليا، ومنجزا وليس معلقا على شرط واقف."},{"kind":"text","text":"أما إذا كان الحق الثابت في السند التنفيذي معلقا على شرط فاسخ، فإنه يكون محقق الوجود صالحا للاقتضاء الجبري. مثال ذلك أن يتضمن عقد البيع الموثق التزاما برد المبيع عند عدم الوفاء بالثمن."},{"kind":"text","text":"كل ما هنالك أنه إذا بدأ التنفيذ بالفعل لاقتضاء الحق الثابت في السند التنفيذي، وتبين للمنفذ ضده أن هذا الحق لم يعد محقق الوجود، بالنظر إلى أن الشرط الفاسخ قد تحقق في وقت لاحق على نشأة السند مثلا، فإن النظام القانوني للتنفيذ يعطيه في هذه الحالة الحق في تقديم إشكال وقتي لوقف التنفيذ مؤقتا، متبوعا بإشكال موضوعي ببطلان إجراءات التنفيذ التي اتخذت بالفعل."},{"kind":"heading","text":"2- معين المقدار"},{"kind":"text","text":"172- من اللازم أن يكون الحق الثابت في السند التنفيذي معين المقدار حتى نكون أمام سند تنفيذي قابل للتنفيذ. فعدم تحديد المقدار يعتبر عذرا يحول بين المدين وبين الوفاء، وبالتالي يعتبر حجة له ألا يخضع لتنفيذ جبري."},{"kind":"heading","text":"3- حال الأداء"},{"kind":"text","text":"173- يجب أن يكون الدين الذي يجري التنفيذ لاقتضائه قد حل أجله وقت البدء في التنفيذ، بل ومن وقت اتخاذ مقدمات التنفيذ. فإذا كان الدين غير حال الأداء وقت إعلان السند التنفيذي وتكليف المدين بالوفاء فإن إجراءات التنفيذ التي ستتخذ ستكون باطلة، حتى ولو كان الأجل قد حل في وقت لاحق. فعواقب التنفيذ الجبري وما تتضمنه من مساس بسمعة المدين وبأمواله، تقتضي عدم البدء فيه- أو حتى اتخاذ مقدماته- إلا بعد اكتمال موجبات حق الدائن في التنفيذ."},{"kind":"text","text":"فإذا كان الحكم قد منح المدين نظرة ميسرة، بأن منحه أجلا للوفاء، فإنه يجب انتظار انقضاء مدة الإمهال هذه حتى يكون الدين الثابت في الحكم حال الأداء."},{"kind":"heading","text":"4- عدم تقادم الحق في التنفيذ"},{"kind":"text","text":"174- المقرر أن الحق الموضوعي لا يتقادم بمرور الزمن (المادة 473 معاملات مدنية)، وأنه لا يسقط مهما كان نوعه إذا حكم به القاضي بحكم لا يقبل الطعن (المادة 485 معاملات مدنية)."},{"kind":"text","text":"ومع ذلك وطبقا لنص المادة 4- 212، فإنه لا يجوز التنفيذ بمقتضى السند التنفيذي- حكما كان أو غيره- إذا ترك مدة خمسة عشر عاما منذ صدوره دون تنفيذ. فامتناع التنفيذ هنا لمرور الزمن يدخل في باب التقادم. وهو تقادم لا يرد على الحق الموضوعي الثابت في الحكم- فهذا الحق على هذا النحو لا يتقادم كما سبق وقلنا حالا- وإنما يرد على السند ذاته كسند تنفيذي، وإن شئت الدقة على الحق في التنفيذ الناشئ عنه. نحن إذا أمام صورة خاصة من صور التقادم هي \"تقادم الحق في التنفيذ\"."},{"kind":"text","text":"على التنفيذ أن يبدأ إذا قبل اكتمال المدة المذكورة، وعندئذ فإن التقادم ينقطع طبقا للقواعد العامة. على أنه إذا بدأت المعاملة التنفيذية ثم تركت غير مكتملة مدة خمسة عشر عاما، فإنه وطبقا لنفس نص المادة المذكورة لم يعد التنفيذ جائزا. أي يحدث أيضا تقادم للحق في التنفيذ."},{"kind":"text","text":"وتقادم الحق في التنفيذ- مثله في ذلك تقادم حق الدعوى- لا يتعلق بالنظام العام. ولذلك لا يجوز لقاضي التنفيذ إثارته من تلقاء نفسه. بينما يملك المنفذ ضده التمسك به من خلال الإشكال الوقتي، وكذلك من خلال الدعوى الموضوعية ببطلان التنفيذ."},{"kind":"text","text":"والواضح أنه بالنظر لعمومية عبارة نص المادة 4- 212، تنطبق قاعدة تقادم الحق في التنفيذ ليس فقط على ذلك الناشئ عن الحكم القضائي وإنما أيضا عن أي من السندات التنفيذية."},{"kind":"heading","text":"الفصل الثاني: أشخاص التنفيذ"},{"kind":"text","text":"175- هم الركن الثاني من أركان التنفيذ. فالتنفيذ الجبري يظل في حالة سكون رغم توافر الركن الأول من أركانه وهو السند التنفيذي، فإذا ظهر أشخاص التنفيذ، انتقل بعدها إلى طور الحركة. فهو ليس عملية تلقائية، وإنما تجري بناء على طلب يقدم من صاحب الحق فيه، إلى قاضي التنفيذ، والذي سيجريه- هو ومعاونوه- على أموال المدين، وفي مواجهته. فالدائن طالب التنفيذ والمدين المنفذ ضده (ويطلق عليهما طرفا التنفيذ) وسلطة التنفيذ (قاضي التنفيذ والقائم بالتنفيذ) هم إذا أشخاص التنفيذ الأربعة الذين لا غنى عنهم في أي معاملة تنفيذ."},{"kind":"text","text":"وسوف نخصص مبحثا مستقلا لكل من قاضي التنفيذ، والقائم بالتنفيذ، وطالب التنفيذ، والمنفذ ضده."},{"kind":"heading","text":"المبحث الأول: قاضي التنفيذ"},{"kind":"text","text":"176- التنفيذ الذي تنشغل به هذه الدراسة هو التنفيذ الذي تستخدم فيه \"الدولة\" قوتها من أجل إجبار المدين على تنفيذ التزامه. والذي يمثل الدولة هنا هو قاض يسمى قاضي التنفيذ، والذي يعاونه في ذلك القائم بالتنفيذ وهو موظف عام أو في حكمه. التنفيذ الجبري إذا هو تنفيذ قضائي، وقاضي التنفيذ هو أول أشخاص التنفيذ في الأهمية."},{"kind":"text","text":"وسوف يتمحور الكلام عن قاضي التنفيذ حول اختصاصه. فتحديد المنازعات التي يختص بالفصل فيها، أو أعمال التنفيذ التي يحق له القيام بها أو الإشراف عليها إنما تدخل في باب اختصاصه النوعي. أما دائرة عمله الجغرافية فإنها تدخل في باب اختصاصه المحلي، ومن ثم- وللغرابة- الولائي."},{"kind":"text","text":"ولذلك سوف نتناول كلا من الاختصاص النوعي والاختصاص المحلي والاختصاص الولائي لقاضي التنفيذ."},{"kind":"heading","text":"المطلب الأول: الاختصاص النوعي"},{"kind":"text","text":"أولا: قاضي التنفيذ هو محكمة مستقلة بذاتها"},{"kind":"text","text":"177- يستفاد من المادة 1-206 وجود قاض للتنفيذ- أو إدارة أو محكمة تنفيذ- في مقر كل محكمة ابتدائية، لكي يختص دون غيره بكل ما يتعلق بالتنفيذ، من إشراف على التنفيذ، وتذليل لعقباته والفصل في منازعاته. وهو يختلف بذلك عن قضاة الدوائر الابتدائية المختصين بالفصل في مختلف المنازعات. يمكن النظر إذا إلى قاضي التنفيذ من حيث ترتيب المحاكم- وعند الاحتياج إلى هذا الترتيب- في درجة أو مستوى الدوائر الابتدائية، وإن كان له اختصاصه المستقل عن الدوائر. ويقصد بهذا الاختصاص المستقل، أن ما يختص به قاضي التنفيذ إنما يكون على سبيل الاستئثار، بحيث لا يجوز لهذه الدوائر أن تزاحمه فيه."},{"kind":"text","text":"ثانيا: قاضي التنفيذ هو صاحب اختصاص نوعي شامل"},{"kind":"text","text":"178- تنص المادة 1-206 على أنه “يختص قاضي التنفيذ دون غيره بتنفيذ السند التنفيذي وبالفصل في جميع منازعات التنفيذ.. كما يختص بإصدار الأحكام والقرارات والأوامر المتعلقة بذلك\". هو إذا ذو اختصاص شامل بكل ما يتعلق بالتنفيذ، ابتداء من الإشراف على تنفيذ السند التنفيذي، ومرورا بإصدار القرارات والأوامر أثناء سيره، وانتهاء بإصدار الأحكام في المنازعات الوقتية أو الموضوعية التي يمكن أن تثور بمناسبته."},{"kind":"text","text":"والأصل أن الحديث عن الاختصاص النوعي للقاضي- أي قاضي- يتناول من ناحية أولى الطلبات التي يختص بالفصل فيها بحكم قضائي (أو ما يسمى بالدعاوى أو المنازعات القضائية)، ويتناول من ناحية ثانية الطلبات التي يصدر بشأنها أمر من الأوامر القضائية، وأشهرها الأوامر على عرائض أو أوامر الأداء (أو ما يسمى بنظام العريضة أو بالأعمال الولائية)."},{"kind":"text","text":"وينطبق كل ما سبق على اختصاص قاضي التنفيذ. فله اختصاص قضائي بمعنى الكلمة يمارسه من خلال الحكم في منازعات التنفيذ، وله اختصاص ولائي يمارسه من خلال الأوامر على عرائض."},{"kind":"text","text":"179- هذا التوافق بين الاختصاص النوعي لقاضي التنفيذ والمفهوم العام للاختصاص النوعي لأي قاض، لا يمنع من وجود بعض التمايز، وتحديدا من حيث الاتساع:"},{"kind":"text","text":"فمن ناحية أولى، يضاف إلى الأوامر على عرائض التي تصدر من قاضي التنفيذ، نوع جديد من الأعمال- سوف نتعرف عليه حالا- هو \"القرارات\". وهي وإن كانت تنتمي إلى الأعمال الولائية للقضاة، إلا أنها ليست من الأوامر، ولا تصدر عادة من عموم القضاة. يجب أن تحظى إذا هذه القرارات بدراسة خاصة عند دراسة الوظيفة الولائية لقاضي التنفيذ."},{"kind":"text","text":"ومن ناحية ثانية، هناك أيضا طائفة كبيرة من \"الأوامر الإدارية\" التي تدخل في الاختصاص النوعي لقاضي التنفيذ بحكم إشرافه على التنفيذ ومعاونيه، ولا تنتمي إلى الأعمال الولائية. صحيح أنه تصدر من عموم القضاة أوامر إدارية، إلا أنها ليست من الاتساع الموجود لدى قاضي التنفيذ. لذلك تحظى الوظيفة الإدارية لقاضي التنفيذ بمكانة خاصة عند دراسة اختصاصه النوعي."},{"kind":"text","text":"ثالثا: الوظيفة الإدارية لقاضي التنفيذ (وظيفة الإشراف على التنفيذ)"},{"kind":"text","text":"180- يختص القاضي-أي قاض- بقدر محدود للغاية من الأوامر الإدارية التي يمكنه إصدارها إلى معاونيه، وخاصة لكاتب الجلسة أو لمكتب إدارة الدعوى. ويختلف الوضع كثيرا عندما نكون أمام قاضي التنفيذ. فالمعاملة التنفيذية مجال رحب للأوامر الإدارية التي تصدر من قاضي التنفيذ. فكل ما يتخذه القائم بالتنفيذ- وهو معظم إجراءات التنفيذ- لا يتخذه إلا بناء على قرارات تصدر إليه من قاضي التنفيذ، بوصفه المشرف على التنفيذ. فالمادة الأولى من المواد المنظمة للتنفيذ الجبري وهي المادة 1- 206 صريحة في أنه \"يجري التنفيذ تحت إشراف قاضي التنفيذ..\"."},{"kind":"text","text":"وظيفة الإشراف على التنفيذ هذه يمارسها قاضي التنفيذ منذ البداية، أي فور قيد طلب التنفيذ، وتستمر طوال المعاملة التنفيذية، يكفي أنه هو الذي يصدر أوامره إلى القائم بالتنفيذ لكي يقوم بالحجز أو بالتنفيذ المباشر أو غير ذلك من إجراءات التنفيذ. ولا تنتهي عملية التنفيذ إلا بقرار يصدر منه أيضا بتسليم أوامر الصرف على خزانة المحكمة."},{"kind":"text","text":"والإشراف يكون عادة في صورة التنبيه باتخاذ إجراء ما واجب قانونا أو الموافقة على اتخاذه، أو بإزالة عقبة ما من عقبات التنفيذ المادية أو القانونية. ووسيلة قاضي التنفيذ في ذلك غالبا، قرار إداري يصدر من رئيس لمرؤوسه- هو القائم بالتنفيذ- بناء على محضر يحرر بمعرفة هذا الأخير قبل اتخاذه للإجراء- رغم أنه هو المختص به قانونا- أو بعد اتخاذه. على أنه ليس بالضرورة أن يكون قرار قاضي التنفيذ المتعلق بالإشراف مكتوبا، إذ لا مانع من أن يكون شفويا. كما أنه ليس بالضرورة أن يتضمن ملف التنفيذ ما يفيد ذلك. فالنصوص حين حددت القائم بالتنفيذ باعتباره المختص بالإجراء، لم تشترط صراحة صدور أمر بذلك من قاضي التنفيذ، إلا أن سلطته في الإشراف هي التي مكنته من ذلك."},{"kind":"text","text":"181- وعندما يقوم قاضي التنفيذ بإصدار أوامر إلى القائم بالتنفيذ، فهو يكون بمثابة موظف عام يصدر قرارات إدارية. فقرارات الإشراف هنا مجرد أوامر من الرئيس إلى المرؤوس دون أن يكون لها مضمون خاص بها مختلف، فهي ليست قرار حجز أو قرار حبس أو غير ذلك مما يؤثر في مصالح الأفراد مباشرة. هي إذا أقرب إلى أعمال الإدارة القضائية التي يلجأ إليها قضاة الموضوع."},{"kind":"text","text":"182- وهذه القرارات الإدارية ليست قابلة للمراجعة. فهي لا تدخل في باب القرارات أو الأوامر المتعلقة بالوظيفة الولائية والتي أجازت المادة 209 التظلم من بعضها واستئناف البعض الآخر. لكنها تدخل في باب أعمال الإدارة القضائية. والمقرر هو عدم جواز الطعن بالإلغاء في هذه الأعمال."},{"kind":"text","text":"رابعا: الوظيفة الولائية لقاضي التنفيذ"},{"kind":"heading","text":"183- يختص قاضي التنفيذ ببعض الأعمال الولائية، يظهر بعضها في صورة أوامر على عرائض، ويظهر معظمها في صورة قرارات."},{"kind":"text","text":"(أ) الأوامر على عرائض"},{"kind":"text","text":"184- تنص المادة 1-206 على اختصاص قاضي التنفيذ \".. بإصدار الأوامر المتعلقة بالتنفيذ..\". كان يمكن إعطاء معنى عام لهذه العبارة بحيث تنصرف إلى كل ما يصدر عن قاضي التنفيذ من أوامر ولائية، أي ما يصدر منه في غير خصومة قضائية، أي إن شئت الدقة ما يصدر منه ولا يعتبر من الأحكام القضائية. فعندئذ يمكن أن تنصرف كلمة الأوامر إلى كل من الأوامر على عرائض، والقرارات التي سنتعرف عليها حالا، والقرارات الإدارية التي تعرفنا عليها قبلا."},{"kind":"text","text":"ولكن لأن العام يؤخذ على عمومه إلا إذا وجد ما يخصصه، فإن عبارة الأوامر محل البحث يجب أن تقتصر على الأوامر على العرائض بمعنى الكلمة، بحيث تخرج القرارات منها، نظرا لإفرادها بعبارة خاصة بها، وكذلك القرارات الإدارية، نظرا لدخولها تحت عبارة أخرى هي الإشراف."},{"kind":"text","text":"وقد ذكرت النصوص بالفعل عدة أوامر على عرائض مما يختص قاضي التنفيذ بإصدارها في مجال التنفيذ."},{"kind":"text","text":"من ذلك الأمر بتنفيذ الأحكام أو الأوامر أو السندات الأجنبية (مادة 222 وما بعدها)، والأمر بتوقيع حجز تحفظي على أموال المدين قبل إعلانه بالسند التنفيذي (مادة 1-234)، والأمر بأن يدفع المحجوز لديه إلى الحاجز المبلغ الذي أقر به في التقرير بما في الذمة (مادة 260)، والأمر بتقدير أجر من يتولى حراسة المنقولات المحجوزة، وذلك إذا كان الحارس شخصا غير المدين (مادة 268) والأمر بأن يتولى الحارس إدارة أو استغلال الأموال المحجوزة (مادة 2- 269)، والأمر بإعفاء الحارس من الحراسة (مادة 1-270)، والأمر بإجراء بيع المنقولات القابلة للتلف في المكان الذي يراه القاضي مناسبا ومن ساعة لساعة (مادة 2-373)، والأمر بالإعلان عن بيع المنقولات المحجوزة في إحدى الصحف اليومية الصادرة في الدولة، أو غيرها من الوسائل التقنية ووسائل الإعلام المختلفة، أو بأي وسيلة أخرى مناسبة (مادة 3- 272)، والأمر بحبس المدين الممتنع عن الوفاء رغم القدرة عليه (مادة 1-319)."},{"kind":"text","text":"ولا يقف اختصاص قاضي التنفيذ بإصدار الأوامر على عرائض عند حد الأوامر السابقة. فهناك حالات عديدة أخرى منصوص عليها، فضلا عن أنه لا توجد حالات محددة حصريا في النظام القانوني الإماراتي تصدر فيها الأوامر على عرائض. إذ لا يوجد ما يمنع قاضي التنفيذ من إصدار أمر على عريضة مقدمة إليه من ذوي الشأن- خاصة طالب التنفيذ أو المنفذ ضده أو القائم بالتنفيذ- في أي شأن يتعلق بالتنفيذ، وتواجدت معه الحاجة إلى اللجوء إلى نظام العريضة بدلا من نظام الدعوى (أو الخصومة أو الحكم)."},{"kind":"text","text":"(ب) القرارات"},{"kind":"text","text":"185- يتفرد قاضي التنفيذ عند ممارسته لوظائفه، بأنه يختلف عن غيره من القضاة، بأنه يصدر إضافة إلى الأحكام والأوامر والقرارات الإدارية، نوع خاص من الأعمال الولائية يسمي بالقرارات. أهم هذه القرارات هي تلك المنصوص عليها في المادة 209 بمناسبة تنظيمها للتظلم أو للاستئناف تجاه بعض أعمال قاضي التنفيذ والتي أسماها النص المذكور بالقرارات."},{"kind":"text","text":"وسوف تكون هذه القرارات محلا لدراسة تفصيلية في وقت لاحق."},{"kind":"heading","text":"المطلب الثاني: الاختصاص المحلي"},{"kind":"heading","text":"186- يوجد في الدولة عدة قضاة تنفيذ بعدد المحاكم الابتدائية على الأقل. ولذلك يجب تحديد الاختصاص المحلي لكل قاض منهم."},{"kind":"text","text":"ويتميز التنظيم القضائي في الدولة بأن قاضي التنفيذ الذي ينعقد له الاختصاص المحلي يمتد اختصاصه إلى كل أنحاء الدولة. ولا يعني ذلك أنه سيكون مضطرا إلى أن يمارس وظائفه حتى خارج الدائرة الجغرافية للمحكمة التي يعمل بها، إذ يستطيع بدلا من ذلك أن ينيب غيره من قضاة التنفيذ."},{"kind":"text","text":"وسوف نتناول في فرع أول تعدد قضاة التنفيذ المختصين محليا، ثم نتناول في فرع ثان امتداد اختصاص قاضي التنفيذ إلى كل الدولة، ثم نتناول في فرع ثالث قاضي التنفيذ المختص محليا عن طريق الندب."},{"kind":"text","text":"الفرع الأول: تعدد قضاة التنفيذ المختصون محليا"},{"kind":"text","text":"187- تحدد المادة 2-207 الاختصاص المحلي لقاضي التنفيذ الذي يجب أن يقيد أمامه هو- وليس غيره- ملف التنفيذ، بالنص على أن \"يكون الاختصاص بالتنفيذ لقاضي التنفيذ في المحكمة التي أصدرت الحكم أو القرار أو الأمر أو جرى في دائرتها توثيق أو تصديق السند التنفيذي أو دائرة المحكمة التي يقع فيها موطن المحكوم عليه أو أموال المحكوم عليه \"."},{"kind":"text","text":"من الواضح إذا أن المادة المذكورة قد اعتمدت عدة معايير للاختصاص المحلي لقاضي التنفيذ، والتي يصلح أي منها لعقد هذا الاختصاص، بحيث يكون هذا القاضي قريبا من مكان صدور السند التنفيذي أو اكتماله أو محل التنفيذ أو موطن المنفذ ضده. فعندما يكون السند التنفيذي حكما صادرا من محكمة العين مثلا، وكان موطن المحكوم عليه مدينة أبو ظبي، ولديه أموال في الظفرة، فإن الاختصاص المحلي بتنفيذ هذا الحكم ينعقد لقاضي التنفيذ الذي يعمل في مقر المحكمة الابتدائية إما التي في العين (بوصفها المحكمة التي أصدرت الحكم) أو التي في أبو ظبي (بوصفها المحكمة التي يقع فيها موطن المحكوم عليه) أو التي في الظفرة (بوصفها المحكمة التي تقع فيها أموال المحكوم عليه)."},{"kind":"text","text":"ولنا على المادة 207 البند (2) والمتعلقة بالاختصاص المحلي لقاضي التنفيذ عدة ملاحظات:"},{"kind":"text","text":"188- الملاحظة الأولى، هناك فرضية أولى يدل عليها النص بوضوح، وهي أن يكون السند التنفيذي سندا قضائيا، وهو ما ينطبق أساسا على الحكم القضائي، والذي يعتبر أبرز السندات التنفيذية عموما والقضائية خصوصا.. فقاضي التنفيذ المختص محليا بالنسبة لهذا الحكم هو بلا منازع ذلك الموجود في مقر المحكمة الابتدائية ذاتها الصادر عنها الحكم، أو أي من قضاة التنفيذ الآخرين المذكورين في النص."},{"kind":"text","text":"189- والملاحظة الثانية، تتعلق بفرضية ثانية يدل عليها نص المادة 2-207 ولكن بعبارات ملتبسة، وهي تتعلق بالسند التنفيذي الصادر من الكاتب العدل، أي بالمحرر الموثق. والمستفاد من النص المذكور هو خضوع الاختصاص المحلي لقاضي التنفيذ هنا لذات المعايير الثلاثة المذكورة أنفا. وأقصد بالعبارات الملتبسة في هذا الصدد أن المدين من حيث الموطن أو مكان الأموال معبر عنه في النص بعبارة المحكوم عليه."},{"kind":"text","text":"190- أما الملاحظة الثالثة فهي تتعلق بالشيك المرتجع كسند تنفيذي. فالمادة 2-207 لم تتعرض لكيفية تحديد الاختصاص المحلي أو المكاني لقاضي التنفيذ في هذه الفرضية. ومن السائغ أن نستبدل كلمة المدين المذكورة في النص بكلمة المحكوم عليه، ونعقد الاختصاص المحلي لقاضي التنفيذ الذي يقع في دائرته الجغرافية موطن المدين أو أمواله. أما المعيار الثالث للاختصاص المحلي، والمعبر عنه في النص بدائرة المحكمة التي أصدرت الحكم أو جرى فيها التوثيق، فيمكن الاعتداد هنا بأي من مراكز الثقل الثلاثة بالنسبة للشيك المرتجع وهي موطن المستفيد وموطن الساحب وموطن البنك -أو فرعه- المسحوب عليه. ولا شك في أرجحية الحل الذي يجعل الاختصاص المحلي لقاضي التنفيذ الذي في المحكمة الابتدائية الواقع في دائرتها هذه المواطن الثلاثة مجتمعة. أما عند توزع هذه المواطن بين عدة إمارات، ويلازمه بالتالي تعدد في المحاكم الابتدائية، فإننا لا نجد ما ينفي اختصاص أكثر من قاض في هذه الحالة."},{"kind":"text","text":"191- أما الملاحظة الرابعة فهي تتعلق بالفرض الذي يكون فيه السند التنفيذي صادرا من لجنة ذات اختصاص قضائي، كلجنة فض المنازعات الإيجارية مثلا. والأصل أن التشريع المنظم لكل لجنة من هذه اللجان هو الذي يحدد الاختصاص بالتنفيذ."},{"kind":"text","text":"الفرع الثاني: امتداد الاختصاص المحلي لقاضي التنفيذ إلى كل الدولة"},{"kind":"text","text":"192- الأصل أن القاضي- أي قاضي- لا يباشر وظائفه إلا في حدود دائرة الاختصاص المكاني للمحكمة التي يعمل بها. ولكن خرج القانون على هذه القاعدة فيما يتعلق بالتنفيذ الجبري. فعندما يتعلق التنفيذ بإجراء يقع في دائرة الاختصاص المحلي لقاضي تنفيذ آخر، فقاضي التنفيذ المختص محليا بملف التنفيذ وفقا لما سبق بيانه، يستطيع أن يمد اختصاصه ويباشر التنفيذ (الإشراف عليه وإصدار القرارات والأوامر المتعلقة به والفصل في منازعاته) حتى في النطاق الجغرافي لهذه الدائرة الأخرى (مادة 3- 212). وينطبق امتداد الاختصاص هذا حتى لو كان الإجراء المطلوب اتخاذه هو إصدار أمر بحبس المدين، وكان موطن هذا الأخير يقع في دائرة محكمة أخرى خلاف المحكمة المنفذ لديها السند التنفيذي (مادة 6- 207)."},{"kind":"text","text":"ومما ساهم في منطقية هذا الحل، النصوص التي تجعل السند التنفيذي الصادر عن إحدى السلطات القضائية الاتحادية أو المحلية قابلا للتنفيذ في جميع أنحاء الدولة."},{"kind":"text","text":"الفرع الثالث: قاضي التنفيذ المختص محليا عن طريق الندب"},{"kind":"text","text":"193- إن امتداد الاختصاص المحلي لقاضي التنفيذ ليشمل كل الدولة ليس معناه حتمية قيام هذا القاضي بوظيفته منفردا في جميع الأحوال وأيا كان مكان اتخاذ الإجراء. فالواقع أن المادة 3-70 تجيز لقاضي التنفيذ المختص محليا والمقيد أمامه ملف التنفيذ، أن ينيب قاضي تنفيذ آخر- هو القاضي المطلوب اتخاذ الإجراء في دائرته- للقيام بذلك (مادة 3- 70)."},{"kind":"text","text":"194- فإذا تمت الإنابة، فإن قاضي التنفيذ المناب يكون هو المختص دون غيره بمباشرة التنفيذ في دائرته، بما في ذلك إصدار القرارات اللازمة لتنفيذ الإنابة، والفصل في إشكالات التنفيذ- الوقتية أو الموضوعية- المعروضة عليه (مادة71)، بل وحتى بيع الأموال المحجوزة. وحتى إذا كانت الإنابة- والتي عبر عنها النص بالإحالة- تتعلق بحبس المدين، فإن القاضي المناب هو الذي يقوم بالتحقيق وإصدار الأمر المناسب وتنفيذه (مادة 6- 70)."},{"kind":"text","text":"195- من المنطقي أيضا أن التظلم من قرارات قاضي التنفيذ المناب إنما يكون أمام رئيس محكمته هو، وأن يكون استئناف هذه القرارات في الأحوال التي تقبل فيها ذلك أمام محكمة الاستئناف في دائرته هو. وهذا بالفعل الحل المقرر صراحة في المادة 2-209من القانون."},{"kind":"text","text":"196- وفضلا عما سبق يكون للسلطة القضائية المطلوب منها تنفيذ الإنابة أن تتقاضي لحسابها ووفقا لقوانينها الرسوم المقررة على أعمال التنفيذ التي تقوم بها (مادة 5-5 من قانون تنظيم العلاقات القضائية)"},{"kind":"heading","text":"المطلب الثالث: الاختصاص الولائي"},{"kind":"text","text":"197- يجب أن يكون قاضي التنفيذ مختصا ليس فقط نوعيا ومحليا وإنما أيضا- وقبل كل ذلك- ولائيا. إذ يجب أن يكون ماثلا في الذهن أن في الدولة جهات قضائية أربع لكل منها نصيب استئثاري من الولاية القضائية- ويدخل في ذلك الإشراف القضائي على التنفيذ وغيره مما يدخل في الاختصاص النوعي لقاضي التنفيذ- لا تزاحمها فيه غيرها."},{"kind":"text","text":"وفي ظل غياب النصوص، ليس أمامنا سوى القول بأن المعيار الذي سيتحدد بناء عليه الاختصاص الولائي لقاضي التنفيذ، هو ذاته المعيار الذي تحدد بناء عليه الاختصاص المحلي. فعندما يكون سند التنفيذ حكما قضائيا مثلا- وهذا هو الغالب- فإن قاضي التنفيذ المختص ولائيا هو قاضي التنفيذ التابع للجهة القضائية الصادر عن محاكمها هذا السند التنفيذي، أو التي فيها موطن المنفذ ضده، أو أمواله. من المتصور إذا أن يوجد قضاة تنفيذ ثلاثة تابعين لجهات قضائية ثلاث، وكل منهم مختص ولائيا بملف التنفيذ. وبطبيعة الحال إذا تم تقديم طلب التنفيذ لأحدهم ارتفع الاختصاص عن الباقين."},{"kind":"text","text":"وإذا كان البحث في مسألة الاختصاص الولائي تكفيه الإحالة إلى قواعد الاختصاص المحلي، فإن النتيجة التي يمكن الوصول إليها بسهولة هي أن \"قاضي التنفيذ المختص محليا هو ذاته المختص ولائيا\"."},{"kind":"text","text":"198- وبناء عليه، فإنه إذا كان القاضي الذي قيد أمامه ملف التنفيذ غير مختص محليا، بينما القاضي المختص تابع لذات جهة القضاء، ففي هذا الفرض سوف نستدعى فقط قواعد الاختصاص المحلي، ولن يثور حديث عن الاختصاص الولائي."},{"kind":"text","text":"199- أما إذا كان القاضي الذي قيد أمامه ملف التنفيذ غير مختص محليا، بينما القاضي المختص تابع لجهة قضاء أخرى، عندئذ نكون أمام عدم اختصاص ولائي، أي أن الاختصاص المحلي ينقلب إلى اختصاص ولائي."},{"kind":"heading","text":"المطلب الرابع: قاضي تنفيذ الأحوال الشخصية (دراسة في خصوصيات تنفيذ السندات المتعلقة بمسائل الأحوال الشخصية)"},{"kind":"text","text":"200- رغم عمومية عبارة أن قاضي التنفيذ هو المختص دون غيره بتنفيذ السند التنفيذي وبالفصل في جميع منازعات التنفيذ وبإصدار الأحكام والقرارات والأوامر المتعلقة ذلك، والواردة في المادة 1-207، إلا أنه يوجد في الحقيقة ما يخصصها أو يعد استثناء عليها. فهناك من منازعات التنفيذ ما جعله المشرع من اختصاص محاكم الموضوع، أي المحاكم الابتدائية. والأخص من ذلك أنه يوجد إلى جانب قاضي التنفيذ- والذي يمكن التعبير عنه بعبارة قاضي التنفيذ العام- قاضي تنفيذ آخر هو قاضي تنفيذ الأحوال الشخصية، يختص هو الآخر دون غيره بتنفيذ السندات التنفيذية المتعلقة بمسائل الأحوال الشخصية، كالنفقة والحضانة وغيرهما، وبالفصل في منازعات التنفيذ."},{"kind":"text","text":"201- وسوف نتناول بطبيعة الحال تحديد اختصاص قاضي تنفيذ الأحوال الشخصية هذا. على أن تكون هذه مناسبة لكي نتعرف أيضا على باقي خصوصيات التنفيذ في مسائل الأحوال الشخصية."},{"kind":"text","text":"الفرع الأول: اختصاص قاضي تنفيذ الأحوال الشخصية"},{"kind":"text","text":"202- قاضي تنفيذ الأحوال الشخصية هو قاض مختص يندب في مقر كل محكمة ابتدائية (مادة 226)، ويعاونه في ذلك عدد كاف من القائمين على التنفيذ والاخصائيين الاجتماعيين (مادة 226)، كما يمكنه عند الاقتضاء أن يستعين بمن يراه من أهل الخبرة والاختصاص في مسائل الأحوال الشخصية (مادة 228)."},{"kind":"text","text":"أولا: الاختصاص النوعي"},{"kind":"text","text":"203- من السهل الوقوف على اختصاص قاضي تنفيذ الأحوال الشخصية، وأنه اختصاص نوعي. والأساس في ذلك هو المادة 227 والتي تنص على أنه\" يختص قاضي تنفيذ الأحوال الشخصية، وحده دون غيره، بتنفيذ السندات التنفيذية والقرارات المتعلقة بأحكام الأحوال الشخصية، والفصل في جميع منازعات وإشكالات التنفيذ، وإصدار أوامر المنع من السفر.. \" فالواضح من هذه المادة أن الاختصاص بتنفيذ السندات التنفيذية المتعلقة بأحكام الأحوال الشخصية- كما لو كانت تتضمن إلزاما بدفع نفقة أو أجر حضانة، أو بتسليم الصغير أو رؤيته أو زيارته أو اصطحابه، أو تتضمن إنفاذا لوصية أو تسليم وارث نصيبه من التركة- ينعقد لقاض محدد هو قاضي تنفيذ الأحوال الشخصية."},{"kind":"text","text":"204- وهذا الاختصاص النوعي إنما هو اختصاص شامل يتناول وفقا للمادة 227 أمورا ثلاثة: فهو يشمل أولا الإشراف على التنفيذ وإصدار القرارات المتعلقة به، وثانيا الفصل في جميع منازعاته الموضوعية منها والوقتية أو ما يسمى بإشكالات التنفيذ، وثالثا إصدار أوامر المنع من السفر. هذا الاختصاص النوعي لقاضي تنفيذ الأحوال الشخصية هو استثناء وارد على الاختصاص النوعي لقاضي التنفيذ العام- إن جاز التعبير- والذي هو المختص دون غيره من حيث المبدأ بالإشراف على تنفيذ مختلف السندات التنفيذية، والفصل في جميع منازعات التنفيذ وبإصدار الأحكام والقرارات والأوامر المتعلقة بذلك (المادة 207)، وكذلك بإصدار أوامر المنع من السفر في بعض الأحوال."},{"kind":"text","text":"205- وتجدر الملاحظة أن نصوص الفصل المنظم لقاضي تنفيذ الأحوال الشخصية لم تشر إلى كونه مختصا بإصدار الأمر بحبس المدين الممتنع عن الوفاء بدين ثابت في سند تنفيذي يتعلق بالأحوال الشخصية. ولذلك يظل الاختصاص بإصدار هذا الأمر خاضعا لحكم المادة 319 وما بعدها، ومن ثم حكرا على قاضي التنفيذ العام إن جاز التعبير."},{"kind":"text","text":"ثانيا: الاختصاص المحلي"},{"kind":"text","text":"206- ليس هناك قاضي تنفيذ أحوال شخصية وحيد في الدولة، وإنما هم قضاة متعددون بتعدد المحاكم الابتدائية المنتدبون في مقارها. ولذلك فإن هذا التعدد يستوجب الوقوف أيضا على القواعد الحاكمة للاختصاص المحلي لقاضي تنفيذ الأحوال الشخصية. وليس هناك نص صريح يتضمن معيار هذا الاختصاص. ومع ذلك يستشف هذا المعيار بكل سهولة من النص الوارد في الفقرة الثانية من226 والتي قررت سريان الأحكام الواردة في قانون الإجراءات على ما لم يرد بشأنه نص في الفصل المنظم لقاضي تنفيذ الأحوال الشخصية. وبالرجوع إلى هذه الأحكام- وتحديدا البند 2 من المادة 207 والذي يتعلق بالاختصاص المحلي لقاضي التنفيذ العام- يجب القول بأن الاختصاص المحلي إنما يكون لقاضي تنفيذ الأحوال الشخصية الذي تقع في دائرته المحكمة التي أصدرت الحكم أو الأمر القضائي سند التنفيذ، أو الذي يقع في دائرته موطن المنفذ ضده أو أمواله."},{"kind":"text","text":"207- ومما يرتبط بالاختصاص المحلي ارتباطا وثيقا، جواز \"الإنابة\" من قاضي تنفيذ الأحوال الشخصية المختص محليا إلى قاضي تنفيذ الأحوال الشخصية المطلوب اتخاذ الإجراء في دائرته، وكذلك جواز \"ضم\" ملفات التنفيذ بين ذات الأطراف والمنظورة أمام قضاة تنفيذ أحوال شخصية متعددين لنظرها أمام القاضي الذي قيد أمامه أول ملف تنفيذ (مادة 2- 96)."},{"kind":"text","text":"الفرع الثاني: إجراءات التنفيذ في مسائل الأحوال الشخصية"},{"kind":"text","text":"208- من المقرر أن هناك مقدمات تسبق التنفيذ الجبري الذي يجري تحت إشراف قاضي التنفيذ، هي تقديم الطلب وإعلان السند التنفيذي والتكليف بالوفاء وانتظار مهلة معينة. ولا تشذ مقدمات تنفيذ السندات المتعلقة بأحكام الأحوال الشخصية عن هذا المقرر. صحيح أن مواد الفصل الخامس المخصص لقاضي تنفيذ الأحوال الشخصية لم تتضمن صراحة من هذه المقدمات سوى واحدة هي انتظار مهلة سبعة أيام من تاريخ إعلان السند التنفيذي (مادة 231)، إلا أن النص على سريان أحكام وإجراءات التنفيذ الواردة في القانون فيما خلت منه المواد الواردة في هذا الفصل الخامس (مادة 226 فقرة ثانية)، يفيد بطريق اللزوم العقلي، سريان النص العام المتضمن لباقي المقدمات، على التنفيذ الذي يزمع إجرائه تحت إشراف قاضي تنفيذ الأحوال الشخصية."},{"kind":"text","text":"209- وإذا كان الأداء المطلوب من المنفذ ضده هو دفع مبلغ من النقود- كما لو كان أداء مبلغ النفقة- فإن التنفيذ سيجري بطريق الحجز. عندئذ، ونظرا لعدم وجود إجراءات خاصة بالحجوز مقررة في الفصل الخامس المخصص لقاضي تنفيذ الأحوال الشخصية، سوف تكون إجراءات الحجوز الواجب اتباعها أمامه هي تلك الإجراءات العامة المقررة في القانون."},{"kind":"text","text":"210- أما إذا كان الأداء المطلوب من المنفذ ضده هو القيام بعمل أو امتناع عن عمل- كما لو كنا بصدد تسليم الصغير لحاضنته أو رؤية الصغير أو زيارته أو اصطحابه- فإن التنفيذ سيكون مباشرا. وهنا أيضا ستكون الأحكام العامة الواردة في القانون هي الواجبة الاتباع بحسب الأصل. هذه الأحكام تعطي لقاضي التنفيذ المختص- والذي قد يكون قاضي تنفيذ الأحوال الشخصية- أن يصدر أمره بتحديد الطريقة التي يتم بها هذا التنفيذ، وتعيين قائم بالتنفيذ للقيام به، وذلك بعد إعلان المنفذ ضده لسماع أقواله (مادة 2-317)."},{"kind":"text","text":"211- ويلاحظ أن الأصل المقرر في نظرية التنفيذ الجبري أن التنفيذ المباشر يكون ممنوعا إذا كان من شأنه المساس بالشخص. هذا الأصل قابل لأن يتعطل عند التنفيذ المباشر في مسائل الأحوال الشخصية. تكفي الإشارة إلى المادة 158 من قانون الأحوال الشخصية والتي تنص على أن\" تنفذ الأحكام الصادرة بضم الصغير وحفظه وتسليمه لأمين والتفريق بين الزوجين ونحو ذلك مما يتعلق بالأحوال الشخصية جبرا ولو أدى ذلك إلى استعمال القوة ودخول المنازل..\"."},{"kind":"text","text":"212- فإذا تعذر التنفيذ المباشر بالطريقة التي حددها قاضي تنفيذ الأحوال الشخصية المختص، أو اقتضى التنفيذ قيام المنفذ ضده به بنفسه ولم يقم بذلك، فلهذا القاضي أن يلزمه بغرامة يومية تصرف كتعويض للمنفذ له."},{"kind":"text","text":"213- ورغم القاعدة التي تلزم القاضي المختص بالتنفيذ باحترام ما ورد في السند التنفيذي، فإن المادة 229 تعطي لقاضي تنفيذ الأحوال الشخصية أن يعرض على أطراف التنفيذ تعديل مواعيد وأماكن الرؤية والزيارة والاصطحاب الواردة في السند التنفيذي، وبشرط عدم الإخلال بمصلحة المحضونين."},{"kind":"text","text":"فلقاضي تنفيذ الأحوال الشخصية أن يعرض الصلح على أطراف التنفيذ (مادة 229). وله أيضا أن يعرض عليهم في أي وقت تعديل مواعيد وأماكن الرؤية والزيارة والاصطحاب ولو كان ذلك يخالف سند التنفيذ، وبشرط عدم الإخلال بمصلحة المحضون (مادة 229). هذا النص أو ذاك هو محض تطبيق للقاعدة العامة المقررة في المادة 77 والتي تعطي للمحكمة عرض الصلح على الخصوم."},{"kind":"text","text":"ولقاضي تنفيذ الأحوال الشخصية أيضا أن يصدق على محاضر الصلح التي تتم بين الأطراف بشأن كيفية تنفيذ السند التنفيذي (مادة 229) أو حتى بشأن ذات الحقوق التي يجري بصددها التنفيذ.. مثال ذلك أن يتضمن الحكم الإلزام بالرؤية دون تحديد، فيتم الصلح على زمان ومكان ذلك. أو أن يكون سند التنفيذ يتضمن ميعادا أو مكانا للرؤية فيتم الصلح المتضمن ميعادا أو مكانا مغايرا للوارد في السند. أو أن يكون سند التنفيذ متضمنا الإلزام بدفع مبلغ معين كنفقة زوجية، فيعرض قاضي تنفيذ الأحوال الشخصية الصلح، ويتم الصلح فعلا على مبلغ أقل أو أكثر، فيصادق عليه. يستوي في كل ذلك الصلح الذي أبرمه أطراف التنفيذ من تلقاء أنفسهم، أو بناء على ما عرضه عليهم القاضي. وكل ذلك أيضا هو محض تطبيق للقاعدة العامة المقررة في المادة 81."},{"kind":"text","text":"ولكن يرد على الصلح المغاير للثابت في السند التنفيذي قيد وحيد، هو عدم الإخلال بمصلحة المحضونين (مادة 229). فلا شك أن من مصلحة المحضون رؤية أبيه غير الحاضن، وبالتالي لا يجوز التصديق على الصلح الذي يؤدي إلى امتناع الرؤية."},{"kind":"heading","text":"214- على قاضي التنفيذ أن يراعي عند التنفيذ العادات والتقاليد والأعراف السائدة في الدولة (مادة 227)."},{"kind":"text","text":"215- تكون جلسات التنفيذ في مسائل الأحوال الشخصية في غير علانية، وتصدر قرارات التنفيذ دون الحاجة إلى عقد جلسة لذلك، ما لم يقرر قاضي تنفيذ الأحوال الشخصية خلاف ذلك (مادة 230). موضع هذه المادة بين النصوص يرجح أنها لا تتكلم عن الفصل في منازعات التنفيذ وإنما عن الإشراف عليه. هذا الإشراف وما يرافقه من إصدار لقرارات تتعلق بالتنفيذ- كالقرار الصادر من قاضي تنفيذ الأحوال الشخصية إلى القائم بالتنفيذ بإجراء الحجز في يوم معين- ليس خصومة قضائية، لأن طلب التنفيذ ليس تحريكا لدعوى قضائية، ولا تنشأ عنه خصومة قضائية، وبالتالي لا يوجد محل في الحقيقة للحديث عن \"جلسة\" أو جلسات بالمعنى القانوني للكلمة. ولذلك لم يكن المشرع في حاجة إلى الحديث عن علانية الجلسات أو عدم علانيتها أو النص على أن يقرر قاضي التنفيذ الدعوة إلى عقد جلسة علنية. وحتى إذا حضر الطرفان أو أحدهما أمام القاضي المختص، فلن نكون أمام جلسة بالمعنى الفني الدقيق."},{"kind":"text","text":"الفرع الثالث: طرق مراجعة قرارات قاضي تنفيذ الأحوال الشخصية"},{"kind":"text","text":"216- تعرضت النصوص المنظمة لقاضي تنفيذ الأحوال الشخصية لطرق مراجعة الأحكام الصادرة منه في منازعات التنفيذ الموضوعية. فقد أجازت المادة 232 الطعن عليها بالاستئناف، وجعلت له ميعادا خاصا."},{"kind":"text","text":"217- وسكتت هذه النصوص عن تنظيم طرق المراجعة في باقي الأحكام أو القرارات أو الأوامر. ولا صعوبة في إخضاع ذلك لما تقرر بشأن قاضي التنفيذ. فالمادة 226 فقرة ثانية واضحة في سريان الأحكام الواردة في القانون فيما خلت منه المواد الواردة في الفصل المتعلق بقاضي تنفيذ الأحوال الشخصية."},{"kind":"text","text":"ومفاد ما سبق وتناغما مع ما تقرر بشأن قرارات قاضي التنفيذ، فالأصل بالنسبة لقرارات قاضي تنفيذ الأحوال الشخصية هو عدم قابليتها للمراجعة إلا في بعض الأحوال الاستثنائية حيث قابلية بعضها للتظلم أو الاستئناف بحسب الأحوال في حدود المنصوص عليه في المادة 209."},{"kind":"heading","text":"المبحث الثاني: القائم بالتنفيذ"},{"kind":"text","text":"218- القائم بالتنفيذ هو كل من كلف بمقتضى القانون أو القرارات النافذة بتولي تنفيذ قرارات قاضي التنفيذ سواء كان موظفا عاما أو شخصا اعتباريا خاصا. ينطبق هذا التعريف إذا على اثنين هما: أولا مأمور التنفيذ، ويقصد به موظف عام يعمل في المحكمة كأحد معاوني قاضي التنفيذ، وثانيا الموظف لدى الشركة الخاصة المتعاقد معها من جانب جهة القضاء للمعاونة في التنفيذ (مادة 206). على أنه يضاف إلى ما سبق، شخصان آخران، هما الشخص الطبيعي والشخص الاعتباري العام، إذا عهد قاضي التنفيذ لأيهما بالمعاونة في التنفيذ، في مجال الحجوز تحديدا (مادة 309)."},{"kind":"text","text":"219- والقائم بالتنفيذ هو أهم معاوني قاضي التنفيذ. ذلك لأن معظم إجراءات التنفيذ إنما تجري بواسطته هو وليس بواسطة قاضي التنفيذ ولا بواسطة أطرافه."},{"kind":"text","text":"فأيا كان شخص القائم بالتنفيذ، أي كل من كلف بتولي تنفيذ قرارات قاضي التنفيذ، فهو المختص باتخاذ الإجراءات التنفيذية، بحيث تكون باطلة إذا لم يتخذها هو، بل وحتى لو اتخذها قاضي التنفيذ بنفسه. يكفي أن إجراءات توقيع الحجز على المنقول- وهو أكثر الحجوز شيوعا- وبكل أنواعه- أي تنفيذيا أو تحفظيا أو لدى الغير- ثم إجراءات بيعه، إنما يتخذها القائم بالتنفيذ وحده، وكذلك الشأن مع التنفيذ العيني أو المباشر، على أن ذلك يكون بصفة ثانوية بالنسبة للحجز على العقار."},{"kind":"text","text":"220- على أنه لا يجب أن يغيب عن البال أن التنفيذ الجبري إنما يجري تحت إشراف قاضي التنفيذ (مادة 1-206)، وأن هذا الأخير هو المختص دون غيره بإصدار القرارات والأوامر المتعلقة بالتنفيذ (مادة 1- 207). كما لا يجب أن يغيب عن البال أيضا أن النصوص تعهد صراحة للقائم بالتنفيذ بأن يتخذ هو معظم الإجراءات التنفيذية، وأنها لا تجعل إشراف قاضي التنفيذ إشرافا سابقا على سبيل الحتم. ولذلك فإن التوفيق بين النصوص يفضي إلى نتيجة مفادها أن هذه الإجراءات إنما تنسب والحال كذلك إلى القائم بالتنفيذ، لأن العبرة في النهاية بمن هو المكلف باتخاذ الإجراء بالفعل. ولذلك لا ينال من صحة الإجراء المكلف به هو، ولا يجعله باطلا، أن يقوم به القائم بالتنفيذ مباشرة وقبل صدور الأمر بذلك، أو أن يقوم به على نحو يتفق مع النصوص وإن بدا مخالفا للأوامر. فالواقع أن حدوث أي من ذلك يجعلنا أمام مجرد مخالفة إدارية من مرؤوس لرئيسه الإداري، وهو ما يستتبع فقط خضوع القائم بالتنفيذ للمساءلة التأديبية."},{"kind":"text","text":"221- على أنه بالإضافة إلى الدور الكبير الذي يقوم به القائم بالتنفيذ خاصة في الحجز على المنقول أو في التنفيذ المباشر، والذي سوف يتم التعرف عليه تفصيلا خلال الدراسة، فمن المفيد تسليط الضوء الآن على بعض جوانب المركز القانوني للقائم بالتنفيذ وهي:"},{"kind":"text","text":"(أ) القيام بالإعلان"},{"kind":"text","text":"222- يعرف القانون كلا من القائم بالتنفيذ والقائم بالإعلان. فالأول هو المكلف بتنفيذ قرارات قاضي التنفيذ، أي بالقيام بمعظم إجراءات التنفيذ الجبري، بينما الثاني هو المكلف بتنفيذ الإعلان القضائي."},{"kind":"text","text":"ولا تخلو أي معاملة تنفيذية من القيام بعدد من الإعلانات، ابتداء من إعلان السند التنفيذي وتكليف المدين بالوفاء، وانتهاء بإعلان قائمة التوزيع المؤقتة لحصيلة التنفيذ. وحصول هذه الإعلانات بمناسبة التنفيذ الجبري لا يغير من وصفها الأصلي وأنها إعلانات قضائية، وذلك لأن هذا التنفيذ يوصف حقيقة بأنه قضائي."},{"kind":"text","text":"ووجود الإعلان القضائي بمناسبة التنفيذ الجبري يثير التساؤل حول الشخص المكلف بالقيام بهذا الإعلان. هل هو القائم بالإعلان أم أنه القائم بالتنفيذ."},{"kind":"text","text":"لا شك أن الانطلاق من الأصل الذي تتضمنه المادة 6 يجعلنا نعهد بهذا الإعلان للقائم بالإعلان. فالمادة المذكورة تنص على أن كل إعلان- وبالتالي أيا كان وسطه الإجرائي ولو كان المعاملة التنفيذية- إنما يجب أن يتم بواسطة القائم بالإعلان."},{"kind":"text","text":"لولا أن تحليل النصوص المنظمة للتنفيذ الجبري يقود إلى استثناء، هو أن الإعلان القضائي في مجال التنفيذ، إنما هو من اختصاص القائم بالتنفيذ وليس القائم بالإعلان."},{"kind":"text","text":"فالمادة 235 تجيز قيام المدين بعرض الوفاء على \"القائم بالتنفيذ عند إعلان السند التنفيذي\" وتحدد دور القائم بالتنفيذ إزاء هذا العرض. هذه العبارة تفيد بمفهوم الإشارة أن المكلف بالإعلان المذكور هو القائم بالتنفيذ وليس القائم بالإعلان."},{"kind":"text","text":"أيضا المادة 253 تحدد كيفية وقوع حجز ما للمدين لدى الغير، وأنه يحصل بموجب أمر بالحجز \"يعلن إلى المحجوز لديه بمعرفة القائم بالتنفيذ\"."},{"kind":"text","text":"وأخيرا- وليس آخرا- فإن المادة 287 تكلف القائم بالتنفيذ وليس القائم بالإعلان، بإعلان الحجز على العقار إلى المدين وغيره من الأشخاص المذكورة فيها."},{"kind":"text","text":"يضاف إلى كل ما سبق، أن باقي النصوص التي تطلبت الإعلان القضائي في مجال التنفيذ، لم يرد فيها ذكر للمختص بذلك أو أنه القائم بالإعلان. صحيح أنها لم تذكر أيضا صراحة أن المختص بذلك هو القائم بالتنفيذ، إلا أنه من المنطق أن نستخلص منها هذا المعنى، وذلك لأنه المتسق مع النصوص الأولى والتي لم تذكر سوى القائم بالتنفيذ."},{"kind":"text","text":"مفاد ما سبق إذا أن المختص بالإعلان القضائي في مجال التنفيذ الجبري هو القائم بالتنفيذ."},{"kind":"text","text":"يبقي بعد ذلك أنه قد يثور في ذهن البعض اعتراض على هذه النتيجة، لكونها تصطدم بالأصل العام المقرر في المادة 6، وهو أن الإعلان يتم بواسطة القائم بالإعلان. ويكفي لتبديد هذه الشبهة التذكير بأن هذه المادة التي تضمنت هذا الأصل هي ذاتها التي أفادت بما يمكن أن يرد عليه من استثناءات. فقد ورد في البند (1) من المادة المذكورة أن الإعلان يكون بواسطة القائم بالإعلان \"أو بالطريقة التي يحددها القانون\"."},{"kind":"text","text":"(ب) عرض الوفاء على القائم بالتنفيذ"},{"kind":"text","text":"223- من الطبيعي أن قيام المدين بالوفاء بالدين الثابت بالسند التنفيذي يمنع الاستمرار فيه. والأصل أن يحصل هذا الوفاء من المدين- أو من الغير- إلى الدائن مباشرة. ولكن يمكن أيضا أن يحصل الوفاء عن طريق العرض على القائم بالتنفيذ. فوفقا للمادة 235 للمدين أن يعرض على القائم بالتنفيذ- عند إعلان السند التنفيذي أو في أي حالة كانت عليها الإجراءات - الوفاء بمحل التنفيذ كله أو بعضه أو تسليمه بحسب الأحوال. وقد أوجب المشرع على القائم بالتنفيذ عند حصول هذا العرض، أن يثبته في محضر، وأن يكلف المدين بالإيداع في خزانة المحكمة لصالح طالب التنفيذ (مادة 1-235). فإذا تم الإيداع بالفعل في ذات اليوم أو اليوم التالي على الأكثر، كان العرض صحيحا، وحق للدائن أن يتسلم ما أودع لصالحه، وامتنع الاستمرار في التنفيذ طالما أن المعروض كان الدين كله. \"أما إذا كان المعروض جزءا من الدين، فعلى القائم بالتنفيذ أن يستمر في التنفيذ بالنسبة للباقي\" (مادة 2- 235)."},{"kind":"text","text":"(ج) كسر الأبواب أو فتح الأقفال بالقوة"},{"kind":"text","text":"224- قد تعترض القائم بالتنفيذ عقبات مادية مثل غلق الأبواب أو وجود أقفال، تحول دون قيامه بواجباته، من حجز أو تنفيذ مباشر كالإخلاء أو التسليم مثلا. وقد يحتاج القائم بالتنفيذ والحال كذلك إلى استعمال القوة لإجراء التنفيذ، كما لو احتاج إلى فتح أبواب أو كسر أقفال بالقوة."},{"kind":"text","text":"لا يمنع المشرع القائم بالتنفيذ من أن يستعمل قوته الذاتية في هذه الحالة. كل ما هنالك أنه وفقا للمادة 235 فإن هذا الاستعمال للقوة مشروط هنا بأمرين: الأول هو حصول القائم بالتنفيذ على موافقة قاضي التنفيذ على استعماله للقوة، والثاني أن يكون استعماله للقوة بحضور أحد أفراد الشرطة وإثبات هذا الحضور في محضر التنفيذ. وقد رتب المشرع بطلان الإجراء بنص خاص وصريح عند المخالفة. وبطبيعة الحال سوف تبطل أيضا إجراءات التنفيذ اللاحقة باعتبار أن ما بني على باطل فهو باطل."},{"kind":"text","text":"(د) عرض الإشكال الوقتي على القائم بالتنفيذ"},{"kind":"text","text":"225- ليس للقائم بالتنفيذ دور تجاه إشكالات التنفيذ الموضوعية، فهذه الأخيرة ترفع إلى المحكمة المختصة- قاضي التنفيذ أو غيره بحسب الأحوال- بصحيفة دعوى تودع لدى مكتب إدارة الدعوى بعيدا عن القائم بالتنفيذ."},{"kind":"text","text":"ولكن يختلف الوضع بالنسبة لدور القائم بالتنفيذ تجاه إشكالات التنفيذ الوقتية، أي منازعات التنفيذ التي يكون المطلوب فيها إجراء وقتيا. إذ يجوز للمنفذ ضده -أو الغير- أن يعرض إشكالا وقتيا عند التنفيذ (مادة 1- 239). ولعل أشهر تطبيقات ذلك طلب وقف التنفيذ عند انتقال القائم بالتنفيذ لتوقيع الحجز على المنقول لدى المدين مثلا. وليس معنى ذلك أن القائم بالتنفيذ مختص بإصدار قرار فاصل في الإشكال. وإنما معناه فقط أن القائم بالتنفيذ يكون مختصا بتلقي هذا الإشكال. وزيادة على ذلك، رتبت النصوص واجبات أخرى على القائم بالتنفيذ عند تلقيه لإشكال وقتي. فمن ناحية أولى يجب على القائم بالتنفيذ التوقف عن التنفيذ فورا، إذا كان الإجراء الذي انتقل لاتخاذه يعتبر متمما للتنفيذ، وذلك لحين صدور قرار في الإشكال من قاضي التنفيذ. ومن ناحية ثانية يجب على القائم بالتنفيذ عرض الإشكال فورا على قاضي التنفيذ ليقرر وقف التنفيذ أو المضي فيه."},{"kind":"heading","text":"المبحث الثالث: طالب التنفيذ"},{"kind":"text","text":"226- سوف يتأكد لنا في وقت لاحق أن طلب التنفيذ هو من مقدمات التنفيذ، وأنه لا غنى عنه بأي حال. مفاد ذلك بطبيعة الحال أن أول من يظهر من أشخاص على مسرح التنفيذ هو مقدم هذا الطلب، والذي تطلق عليه النصوص عبارة \"طالب التنفيذ\". هذا الأخير هو إذا من أشخاص التنفيذ، وتحديدا أحد طرفي رابطة التنفيذ التي لا تقوم لها قائمة بدونهما. طالب التنفيذ هو أيضا من سيقوم باتخاذ إجراءات تنفيذية عديدة لاحقة يلقيها المشرع على عاتقه."},{"kind":"text","text":"227- (أ) والذي يجوز له أن يحمل صفة طالب التنفيذ بحق، هو صاحب الحق في التنفيذ وهو ذاته الشخص صاحب الحق الموضوعي والثابت اسمه في السند التنفيذي. فهو المحكوم له في الحكم القضائي مثلا. يستوي بعد ذلك أن يكون طالب التنفيذ طالبا له بشخصه، أو بواسطة ممثله القانوني، أو ممثله الاتفاقي."},{"kind":"text","text":"وطالب التنفيذ بشخصه لا يثير مشكلة في فهم المقصود به. فهو صاحب الحق في التنفيذ الذي يطلب شخصيا التنفيذ. تتوافر هذه الصفة أيضا في طالب التنفيذ عندما يكون شخصا معنويا."},{"kind":"text","text":"228- (ب) أما طالب التنفيذ بواسطة ممثله القانوني، فهو الحالة التي يكون فيها صاحب الحق في التنفيذ- وهو كما قلنا ذاته صاحب الحق الموضوعي الثابت اسمه في السند التنفيذي- فاقدا للأهلية الإجرائية، كما لو كان قاصرا أو محجورا عليه، ويكون له بالتالي ممثل قانوني، كالولي أو الوصي أو القيم. هذا الممثل تكون له الصفة الإجرائية في طلب التنفيذ نيابة عن صاحب الحق. أما إذا سعى فاقد الأهلية الإجرائية أن يكون طالبا للتنفيذ بشخصه، فإن سعيه سيكون مردودا عليه. إذ يجوز للمنفذ ضده في هذا الفرض، ومن خلال الاستشكال في التنفيذ، وقفه وكذلك إبطاله."},{"kind":"text","text":"229- (ج) أما طالب التنفيذ بواسطة ممثله الاتفاقي، فهو الحالة التي يصدر فيها توكيل من صاحب الحق في التنفيذ بالمعنى السابق تحديده إلى أحد المحامين لاتخاذ إجراءات التنفيذ، أو التي يكون فيها طالب التنفيذ هو الوكيل في التصرف القانوني ذاته الذي يراد طلب تنفيذ السند المتعلق به."},{"kind":"text","text":"230- (د) وكما تتوافر صفة طالب التنفيذ لصاحب الحق الموضوعي الثابت في السند التنفيذي، فإنها قد تتوافر أيضا فيما بعد لخلفه العام أو الخاص. فقد يتوفى صاحب هذا الحق قبل أن يطلب التنفيذ، وعندئذ يكفي ورثته مثلا- وهم أشهر خلفه العام- إثبات صفتهم هذه حتى يكون لهم الحق في طلب التنفيذ واكتساب صفة طالب التنفيذ. وما يصدق على الخلف العام يصدق أيضا على الخلف الخاص، كالمحال إليه الحق الثابت في السند التنفيذي."},{"kind":"text","text":"231- (ه) وقد تثبت صفة طالب التنفيذ لشخص معين مع بدء التنفيذ، ثم يتوفى في وقت لاحق أو يفقد أهليته أو تزول صفة من كان يباشر الإجراءات بالنيابة عنه. لا شك أن هذا العارض أو ذاك من شأنه حرمان طالب التنفيذ - والذي كان يتابع الإجراءات بشخصه أو بواسطة ممثله القانوني بحسب الأحوال- من متابعة التنفيذ. ولذلك تنص المادة 2-237 على وقف إجراءات التنفيذ في هذه الحالة إلى أن يتم تعجيلها من جانب أحد طرفي التنفيذ. ويستفاد من المادة المذكورة أن هذا الوقف للتنفيذ يحدث بقوة القانون. ولذلك يجب على قاضي التنفيذ أن يمتنع- ومن تلقاء نفسه- عن الاستمرار في التنفيذ طالما ظهر من ملف التنفيذ ما يفيد حدوث العارض. فإذا لم يحدث هذا الوقف واستمر التنفيذ، فإنه يكون باطلا. ولذلك، فبعد أن يظهر طالب التنفيذ في ثوبه الجديد، يصير بإمكانه الاستشكال في التنفيذ الحاصل منذ حدوث العارض، بأن يطلب بطلانه إذا كانت له مصلحة في ذلك."},{"kind":"text","text":"أما إذا كنا أمام طالب تنفيذ يظهر بواسطة ممثله الاتفاقي، أي وكيله بالمعنى السابق تحديده، وحدث أن انقضت الوكالة بوفاة الوكيل أو بانقضاء وكالته بالتنحي أو بالعزل، فإن هذا العارض لا يؤثر على سير إجراءات التنفيذ. السند في ذلك هو أولا عدم وجود نص يرتب أثرا على هذا العارض إذا حدث لطالب التنفيذ. وثانيا القياس على ما هو مقرر بشأن الخصومة القضائية. فوفقا لهذا القياس ليس أمام طالب التنفيذ في الحالة محل البحث سوى متابعة الإجراءات بنفسه أو تعيين وكيل آخر إن رغب في ذلك."},{"kind":"text","text":"232- نختم الحديث عن طالب التنفيذ ببيان أهم الأعباء الإجرائية الواقعة مبكرا على عاتقه. هذه الأعباء هي أولا سداد رسوم التنفيذ المقررة عند قيد ملف التنفيذ، وثانيا تعيين موطن مختار له في دائرة المحكمة التي يجري فيها التنفيذ، وثالثا تحديد طريق التنفيذ الذي يرغبه ولوازم ذلك."},{"kind":"heading","text":"المبحث الرابع: المنفذ ضده"},{"kind":"text","text":"233- رغم أن التنفيذ الجبري يجري من حيث المبدأ على المال وليس على الشخص، إلا أن إجراءاته لابد وأن يتم اتخاذها في مواجهة شخص معين، هو المدين بالحق الموضوعي والثابت اسمه في السند التنفيذي. هذا الشخص يسمى بالمنفذ ضده. هذا الأخير إذا هو الطرف الثاني في رابطة التنفيذ، أو في الحق في التنفيذ. لا يتصور إذا تنفيذ صحيح إلا إذا كان هناك منفذ ضده يحمل هذه الصفة بحق."},{"kind":"text","text":"فعندما يجري تنفيذ بمقتضى الحكم القضائي- وهو أشهر السندات التنفيذية- فإن المحكوم عليه الثابت اسمه في هذا الحكم هو الذي يجب أن يأخذ صفة المنفذ ضده، والذي يجب أن تتخذ في مواجهته كل إجراءات التنفيذ. فهذا الشخص تحديدا هو الذي يجب ذكره كمنفذ ضده في طلب التنفيذ، وهو أيضا الذي يجب إعلانه بالسند التنفيذي وتكليفه بالوفاء، وهو كذلك ما سيحمل فيما بعد صفة المحجوز عليه إذا ما جرى التنفيذ- وهذا هو الغالب- بطريق الحجز، وهو الذي يجب أن يكون المال المحجوز مملوكا له وليس لغيره، ثم إنه الذي تتوافر فيه غالبا الصفة اللازمة للاستشكال في التنفيذ."},{"kind":"text","text":"وكما رأينا بالنسبة لطالب التنفيذ، فإن المنفذ ضده قد يكون بشخصه أو بواسطة ممثله القانوني أو بوكيله."},{"kind":"text","text":"234- (أ) فالمنفذ ضده بشخصه هو الأصل. ويتوافر هذا الوصف عندما يقدم طلب التنفيذ ضد المدين الثابت اسمه في السند التنفيذي، وكان كامل الأهلية الإجرائية، ولم يعين عنه وكيلا. تتوافر هذه الصفة أيضا في المنفذ ضده عندما يكون شخصا معنويا.."},{"kind":"text","text":"235- (ب) وكما تتوافر صفة المنفذ ضده بشخصه للمدين الثابت اسمه في السند التنفيذي، فإنها قد تتوافر أيضا فيما بعد لخلفه الخاص وبشخصه. ومن النادر أن يحدث ذلك في الواقع العملي، إلا أنه يمكن التمثيل على ذلك بأن يحيل المدين دينه النقدي الثابت في السند التنفيذي إلى الغير، وتكون الحوالة نافذة في حق الدائن. عندئذ لن يصلح المدين لكي يحمل صفة المنفذ ضده، وإنما يجب أن يحملها المحال عليه."},{"kind":"text","text":"236- (ج) أما المنفذ ضده بممثل قانوني، فهو الوصف الصحيح للمدين الثابت اسمه في السند التنفيذي ولم تكن لديه الأهلية الإجرائية، كالصغير والمحجور عليه. إذ يتم حينئذ اتخاذ الإجراءات في مواجهته من خلال ممثله القانوني، كوليه أو وصيه أو القيم عليه."},{"kind":"text","text":"237- (د) وأما المنفذ ضده بممثل اتفاقي، فهو من حيث المبدأ المدين الثابت اسمه في السند التنفيذي كأصيل، والثابت أيضا أن مديونيته هذه قد نشأت من خلال وكيله بالتصرف. فعندئذ يجوز للدائن التنفيذ على المدين- وبمعنى أدق على أموال المدين- ويكون هو من يحمل صفة المنفذ ضده، وإن كان طلب التنفيذ ومباشرة الإجراءات يتم في مواجهة الوكيل."},{"kind":"text","text":"238- (ه) وكما رأينا بالنسبة لطالب التنفيذ، فإنه قد يحدث عارض للمنفذ ضده قبل البدء في التنفيذ أو قبل إتمامه. ونقصد بهذا العارض وفاة المنفذ ضده أو فقده للأهلية أو زوال صفة من كان يباشر الإجراءات بالنيابة عنه. في هذه الحالة لا يجوز البدء في التنفيذ أو الاستمرار فيه إلا بعد إعلان الورثة أو من يقوم مقام المدين بالسند التنفيذي وانتظار سبعة أيام من تاريخ الإعلان (مادة 1-237)."},{"kind":"heading","text":"المبحث الخامس: الغير"},{"kind":"text","text":"239- الأصل أن التنفيذ الجبري يجري بناء على طلب الدائن في مواجهة المدين وعلى أموال هذا الأخير. هذا الدائن وذاك المدين هما طرفا رابطة التنفيذ، معنى ذلك أن غيرهما لا شأن له بالتنفيذ. فلن تتخذ إجراءات التنفيذ بناء على طلبه أو في مواجهته، ولن يرتب التنفيذ أي أعباء إجرائية عليه، كما لن يعود عليه أيضا بأي منفعة."},{"kind":"text","text":"ولكن ليس معنى ذلك أن التنفيذ لن يمس غير أطراف الحق في التنفيذ. ففي التنفيذ بطريق الحجز على العقار، لا مانع من أن يجري التنفيذ على عقار الكفيل العيني، رغم أنه ليس مدينا أصليا لطالب التنفيذ. على أن هذا الكفيل ليس في الحقيقة من الغير، وإنما ينتمي إلى الطرف السلبي في رابطة التنفيذ، أي المدين. فهذا الكفيل هو مدين لطالب التنفيذ وإن كان بصفة تبعية."},{"kind":"text","text":"أيضا لا مانع من أن يجري تنفيذ على عقار الحائز، رغم أنه ليس مدينا بالمرة لطالب التنفيذ ولا حتى مدينا لمدينه. هو إذا ليس طرفا في الحق في التنفيذ. ومع ذلك فإن التنفيذ سيجري في مواجهته، وسيعتبر من أطراف التنفيذ وليس من الغير."},{"kind":"text","text":"أيضا قد يجري تنفيذ خاطئ على مال مملوك لغير المدين. هنا لن يكون هذا الغير طرفا في رابطة التنفيذ، ولن يكون مكلفا بالاشتراك في عملية التنفيذ. فهو ليس محملا بأي أعباء إجرائية تتعلق بالتنفيذ. على أن هذا لا يمنعه من طلب استرداد أو استحقاق ماله المحجوز في أي وقت، ولو بعد انتهاء التنفيذ."},{"kind":"text","text":"نأتي الآن إلى الغير بمعنى الكلمة، أي الشخص الذي ليس طرفا في الحق في التنفيذ وبالتالي ليس طالبا للتنفيذ وليس منفذا ضده، ومع ذلك سيعتبر طرفا ثالثا في رابطة التنفيذ، نظرا لأنه سيتخذ في مواجهته إجراء من إجراءات التنفيذ- هو الحجز- كما يحمله المشرع بأعباء إجرائية تتعلق بالتنفيذ. نقصد بذلك تحديدا المحجوز لديه في حجز ما للمدين لدى الغير. فهذا الأخير هو الذي توجه إليه ورقة الحجز والتي ترتب اعتبار المال الذي تحت يده محجوزا، وهو الذي يلتزم بإيداع ما في ذمته خزانة المحكمة الآمرة بالحجز أو بتقديم تقرير صحيح بما في الذمة، وهو أخيرا الذي يدفع إلى الحاجز حقه في حدود المبلغ الذي أقر به."},{"kind":"heading","text":"الفصل الثالث: محل التنفيذ"},{"kind":"text","text":"تمهيد"},{"kind":"heading","text":"240- الاهتمام ينصب على محل التنفيذ بطريق الحجز:"},{"kind":"text","text":"ينقسم التنفيذ الجبري ابتداء إلى نوعين هما التنفيذ المباشر (أو العيني)، والتنفيذ غير المباشر والمسمى بالتنفيذ بطريق الحجز. والنوع الأول من أنواع التنفيذ هو الطريق الواجب اتباعه عندما يكون الإلزام الذي يتضمنه السند التنفيذي منصبا على أداء أي شيء غير النقود. مثال ذلك أن يكون المطلوب من المدين تسليم منقول معين أو عقار، أو القيام بالبناء أو الإخلاء. في مثل هذه الحالات لا يثير محل التنفيذ مشكلة، فهو عين ما ألزم السند التنفيذي به المدين."},{"kind":"text","text":"أما عندما يكون الإلزام الذي يتضمنه السند التنفيذي منصبا على أداء مبلغ من النقود، فعندئذ يكون طريق التنفيذ الواجب الاتباع هو التنفيذ بطريق الحجز. وهنا قد يقع الحجز على عين ما التزم به المدين وهو النقود. إلا أنه كثيرا ما تكون هذه النقود خافية. ولذلك أجاز القانون الحجز على أي مال آخر من أموال المدين. مثل هذا الوضع يثير عدة تساؤلات استوجبت من المشرع الإجابة عليها."},{"kind":"text","text":"ولذلك سوف ينصب اهتمامنا على الإجابات التي يتحدد على ضوئها محل التنفيذ الذي يجري بطريق الحجز."},{"kind":"text","text":"241- فالمبحث الأول سيخصص لدراسة شروط المال محل التنفيذ. وسوف يبين من هذه الشروط أن هناك من الأموال مالا يجوز الحجز عليه. هذه الأموال سيخصص لها المبحث الثاني من هذا الفصل. ويثور تساءل أخير عن مدى ضرورة التناسب بين المال المحجوز والحق المحجوز من أجله، وما إذا كانت هناك وسائل لإعادة هذا التناسب إذا كان مفتقدا. والمبحث الثالث سوف يخصص لدراسة هذا الموضوع."},{"kind":"heading","text":"المبحث الأول: شروط المال محل التنفيذ"},{"kind":"heading","text":"242- محل التنفيذ بطريق الحجز يجب أن يكون مالا، مملوكا للمدين، وقابلا للتصرف فيه، وقابلا أيضا للحجز عليه."},{"kind":"text","text":"وسوف نتعرف على كل صفة من هذه الصفات في مطلب مستقل."},{"kind":"heading","text":"المطلب الأول: محل التنفيذ مال"},{"kind":"text","text":"243- الأموال هي النقود أو الحقوق المالية الواردة على منقول أو عقار، كحق الملكية أو غيره من الحقوق التي تتفرع عنه. ولذلك يجوز الحجز على حق الانتفاع والذي هو حق عيني متفرع من حق الملكية، ويخول المنتفع استعمال واستغلال أموال تخص آخر، مادامت قائمة على حالها وعلى ثمار الشيء المنتفع به"},{"kind":"text","text":"أما الحقوق غير المالية، فإنها لا تصلح محلا للتنفيذ. ينطبق ذلك على حقوق الشخصية أو ما يسمى بالحقوق الملازمة للشخصية."},{"kind":"text","text":"244- (أ) أهم هذه الحقوق هو الجانب الأدبي من حق المؤلف. وبناء عليه لا يجوز الحجز على أصل المصنفات غير المنشورة للمؤلف، حتى بعد وفاته. إذ للمؤلف وحده- أو لورثته من بعده- الحق في أن يقرر نشر مصنفه."},{"kind":"text","text":"أما الحقوق المالية للمؤلف على مصنفه المنشور، فهذه تمثل الجانب المالي من حق المؤلف، ولا يوجد ما يمنع من الحجز عليها. فيمكن الحجز على النسخ المطبوعة أو على ثمنها أو على ما يستحق للمؤلف في ذمة الناشر."},{"kind":"heading","text":"245- (ب) كما لا يجوز الحجز على باقي حقوق الشخصية، كالحق في الاسم أو الشهادة العلمية بالنسبة للإنسان."},{"kind":"text","text":"246- (ج) أيضا فإن المراسلات الخاصة والمذكرات الشخصية- ورقية كانت أو الكترونية- تتضمن عادة أسرارا خاصة- مما يدخل في حقوق الشخصية- بحيث لا تجوز إذاعتها إلا بموافقة ذوي الشأن. لذلك لا يجوز الحجز عليها لعدم جواز بيعها جبرا، لما يترتب على مخالفة ذلك من إفشاء لمحتواها."},{"kind":"heading","text":"المطلب الثاني: المال مملوك للمدين"},{"kind":"text","text":"247- يستوي أن يكون المدين مدينا أصليا أو تبعيا كالكفيل. كما يستوي أن يكون المال مملوكا ملكية مفرزة أو شائعة. فالمهم أن يكون هذا المدين واردا اسمه في السند التنفيذي."},{"kind":"text","text":"فإذا لم يعد المال مملوكا للمدين وقت البدء في التنفيذ، فإن الحجز عليه لا يجوز، سواء كان المال موجودا وقت نشوء الحق الذي يراد استيفاؤه جبرا، أم وجد في ذمة المدين بعد نشوء هذا الحق."},{"kind":"text","text":"248- وعندما يكون المدين شخصا اعتباريا كالشركة، فإن للشركة ذمة مالية مستقلة ومنفصلة عن ذمم الشركاء، ويترتب على ذلك أن حصة الشريك تخرج عن ملكيته وتنتقل إلى الشركة (مادة 18 من قانون الشركات التجارية)، وبالتالي لا يجوز لدائن أحد الشركاء اقتضاء حقه من حصة مدينه في رأس مال الشركة (مادة 1-20 من قانون الشركات التجارية). لا يجوز لهذا الدائن إذا الحجز على شيء من أموال الشركة حتى ولو كان هذا المال هو ما قدمه مدينه كحصة في رأس مال الشركة، لكن يجوز لهذا الدائن أن يقتضي حقه من نصيب مدينه في الأرباح، وكذلك من النصيب الذي يؤول إليه بعد تصفية الشركة (مادة 1-20 من قانون الشركات التجارية)."},{"kind":"text","text":"أما دائن الشركة فإنه يستطيع بطبيعة الحال الحجز على أموال الشركة- بما في ذلك حصص الشركاء- لكنه لا يستطيع الحجز على أموال الشركاء الأخرى."}]);
